package com.contractguard;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

/**
 * Contract Guard — API contract registry and breaking-change detection platform.
 *
 * Modular monolith: pure-Java core packages (specs, compatibility, consumers, impact,
 * policy, domain) hold no Spring annotations and no I/O; Spring lives only at the
 * edges (api, persistence, notify, audit).
 */
@SpringBootApplication
public class Application {

    public static void main(String[] args) {
        SpringApplication.run(Application.class, args);
    }
}

package com.contractguard.api;

import java.time.Instant;
import java.util.LinkedHashMap;
import java.util.Map;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/**
 * Liveness probe: confirms the HTTP layer, the H2 database and the webhook
 * receiver configuration are reachable/configured.
 */
@RestController
@RequestMapping("/api/health")
public class HealthController {

    private final JdbcTemplate jdbc;
    private final String webhookUrl;

    public HealthController(JdbcTemplate jdbc,
                            @Value("${contractguard.webhook-url}") String webhookUrl) {
        this.jdbc = jdbc;
        this.webhookUrl = webhookUrl;
    }

    @GetMapping
    public Map<String, Object> health() {
        Map<String, Object> body = new LinkedHashMap<>();
        body.put("status", "UP");
        body.put("service", "contractguard");
        body.put("time", Instant.now().toString());
        body.put("webhook_url", webhookUrl);
        body.put("db", databaseStatus());
        return body;
    }

    private String databaseStatus() {
        try {
            jdbc.queryForObject("SELECT 1", Integer.class);
            return "UP";
        } catch (RuntimeException e) {
            return "DOWN: " + e.getClass().getSimpleName();
        }
    }
}

/**
 * Append-only audit history of attempt transitions (actor, timestamp, justification).
 * Rows are never updated or deleted.
 */
package com.contractguard.audit;

/**
 * Webhook notifications to the untouched starter-kit receiver (HTTP POST,
 * fire-and-forget with one retry). Delivery failure is logged in the notifications
 * table and never blocks the publishing pipeline.
 */
package com.contractguard.notify;

/**
 * Persistence: JdbcTemplate DAOs over the H2 schema (schema.sql). One transaction per
 * pipeline stage. Contains no business logic.
 */
package com.contractguard.persistence;

package com.contractguard.specs;

import java.util.List;

/**
 * One structural validation error, with the JSON pointer of the offending node.
 * Collected in bulk: validation never fails fast, so a single upload reports every
 * problem (e.g. all unresolved $refs at once).
 */
public record SpecValidationError(String pointer, String message) {

    @Override
    public String toString() {
        return pointer + ": " + message;
    }
}

package com.contractguard.specs;

import java.util.List;

/**
 * Thrown when a specification fails parsing or structural validation. Carries every
 * collected error (never just the first) so callers can render a complete diagnosis.
 */
public class SpecParseException extends RuntimeException {

    private final List<SpecValidationError> errors;

    public SpecParseException(List<SpecValidationError> errors) {
        super("spec validation failed with " + errors.size() + " error(s): "
                + String.join("; ", errors.stream().map(SpecValidationError::toString).toList()));
        this.errors = List.copyOf(errors);
    }

    public List<SpecValidationError> getErrors() {
        return errors;
    }
}

package com.contractguard.specs;

import java.util.Optional;

/**
 * A field or operation found with {@code deprecated: true}, plus its optional
 * {@code x-sunset} date. Scanning is generic (any node with {@code deprecated});
 * classification into findings happens later in the pipeline.
 */
public record DeprecationRecord(String pointer, String humanPath, Optional<String> sunsetRaw,
                                Optional<java.time.LocalDate> sunset) {
}

package com.contractguard.specs;

import io.swagger.v3.oas.models.OpenAPI;

import java.util.List;
import java.util.Map;

/**
 * A successfully parsed and validated specification. Holds the canonical form (for
 * duplicate detection), the effective wire-contract map (for compatibility analysis)
 * and the deprecation scan. The typed swagger-core model is carried for later pipeline
 * stages but is intentionally not serialized.
 */
public final class SpecDocument {

    private final String openapiVersion;
    private final String title;
    private final String specVersion;
    private final String canonicalJson;
    private final Map<String, String> effectiveSchemas;
    private final List<DeprecationRecord> deprecations;
    private final transient OpenAPI model;

    public SpecDocument(String openapiVersion, String title, String specVersion,
                        String canonicalJson, Map<String, String> effectiveSchemas,
                        List<DeprecationRecord> deprecations, OpenAPI model) {
        this.openapiVersion = openapiVersion;
        this.title = title;
        this.specVersion = specVersion;
        this.canonicalJson = canonicalJson;
        this.effectiveSchemas = Map.copyOf(effectiveSchemas);
        this.deprecations = List.copyOf(deprecations);
        this.model = model;
    }

    public String getOpenapiVersion() { return openapiVersion; }
    public String getTitle() { return title; }
    public String getSpecVersion() { return specVersion; }
    public String getCanonicalJson() { return canonicalJson; }
    public Map<String, String> getEffectiveSchemas() { return effectiveSchemas; }
    public List<DeprecationRecord> getDeprecations() { return deprecations; }
    public OpenAPI getModel() { return model; }
}

package com.contractguard.specs;

import java.util.ArrayList;
import java.util.List;

/**
 * Normalizes endpoint path templates to a shape in which placeholder names are ignored
 * and only their positions count: {@code /quotes/{id}} and {@code /quotes/{quoteId}}
 * both normalize to {@code /quotes/{0}}. This is what lets consumer bindings written
 * against one parameter naming keep matching the same operation after a rename.
 */
public final class PathShapes {

    private PathShapes() {
    }

    public static String normalize(String rawPath) {
        if (rawPath == null || rawPath.isBlank()) {
            return "/";
        }
        String trimmed = rawPath.trim();
        if (!trimmed.startsWith("/")) {
            trimmed = "/" + trimmed;
        }
        String[] segments = trimmed.split("/", -1);
        List<String> out = new ArrayList<>();
        int ordinal = 0;
        for (String segment : segments) {
            if (segment.isEmpty()) {
                continue; // leading slash; consecutive slashes collapse
            }
            if (segment.startsWith("{") && segment.endsWith("}") && segment.length() >= 2) {
                out.add("{" + ordinal++ + "}");
            } else {
                out.add(segment);
            }
        }
        return "/" + String.join("/", out);
    }
}

package com.contractguard.specs;

/**
 * A wire location: HTTP method + normalized path shape + one of the scopes
 * {@code requestBody}, {@code param:<in>:<ordinal>} or {@code response:<status>}.
 * Two specifications with equal effective-schema maps for all locations have equal
 * wire contracts, regardless of component naming or internal $ref layout.
 */
public record EffectiveLocation(String method, String pathShape, String scope) {

    public String key() {
        return method + " " + pathShape + " :: " + scope;
    }
}

package com.contractguard.specs;

import java.util.Optional;

import tools.jackson.databind.JsonNode;

/**
 * Resolves local JSON-pointer references ({@code #/...}) against the document root.
 * Handles pointer escaping ({@code ~0}, {@code ~1}). Used by the structural validator
 * (target must exist) and by the effective-schema extractor (targets are expanded).
 */
final class RefResolver {

    private RefResolver() {
    }

    static boolean isLocalRef(String ref) {
        return ref != null && ref.startsWith("#/");
    }

    /** Resolves a local pointer; empty if the target does not exist. */
    static Optional<JsonNode> resolve(JsonNode root, String ref) {
        if (!isLocalRef(ref)) {
            return Optional.empty();
        }
        JsonNode current = root;
        for (String rawToken : ref.substring(2).split("/", -1)) {
            String token = rawToken.replace("~1", "/").replace("~0", "~");
            if (token.isEmpty() && current != null && !current.isMissingNode()) {
                // "//" or trailing "/": only legal as the root pointer "#/", handled above
                if (ref.equals("#/")) {
                    return Optional.of(current);
                }
                return Optional.empty();
            }
            if (current == null || current.isMissingNode()) {
                return Optional.empty();
            }
            if (current.isArray()) {
                int index;
                try {
                    index = Integer.parseInt(token);
                } catch (NumberFormatException e) {
                    return Optional.empty();
                }
                if (index < 0 || index >= current.size()) {
                    return Optional.empty();
                }
                current = current.get(index);
            } else if (current.isObject()) {
                current = current.get(token);
                if (current == null || current.isMissingNode()) {
                    return Optional.empty();
                }
            } else {
                return Optional.empty();
            }
        }
        if (current == null || current.isMissingNode()) {
            return Optional.empty();
        }
        return Optional.of(current);
    }
}

package com.contractguard.specs;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

import tools.jackson.databind.JsonNode;

/**
 * Canonicalization: converts a Jackson tree into a plain Map/List structure with sorted
 * object keys and a sorted {@code required} array (it is semantically a set). Component
 * names and $ref placement are deliberately NOT erased here — that is the effective-schema
 * expander's job — so the whole-document canonical form still distinguishes genuinely
 * different documents while being insensitive to key order and formatting.
 */
final class CanonicalJson {

    private CanonicalJson() {
    }

    /** Canonicalizes a node into JSON-serializable Maps/Lists (sorted keys). */
    static Object canonicalize(JsonNode node) {
        if (node == null || node.isNull() || node.isMissingNode()) {
            return null;
        }
        if (node.isObject()) {
            Map<String, Object> sorted = new TreeMap<>();
            node.fields().forEachRemaining(entry -> {
                String key = entry.getKey();
                JsonNode value = entry.getValue();
                if ("required".equals(key) && value.isArray()) {
                    sorted.put(key, sortedTextList(value));
                } else {
                    sorted.put(key, canonicalize(value));
                }
            });
            return sorted;
        }
        if (node.isArray()) {
            List<Object> list = new ArrayList<>();
            node.elements().forEachRemaining(element -> list.add(canonicalize(element)));
            return list;
        }
        if (node.isTextual()) {
            return node.textValue();
        }
        // numbers, booleans, etc.: pass the node through; Jackson serializes it as-is
        return node;
    }

    private static List<String> sortedTextList(JsonNode array) {
        List<String> values = new ArrayList<>();
        array.elements().forEachRemaining(element -> {
            String text = element.isTextual() ? element.textValue() : element.toString();
            if (text != null) {
                values.add(text);
            }
        });
        java.util.Collections.sort(values);
        return values;
    }
}

package com.contractguard.specs;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.Iterator;
import java.util.List;
import java.util.Map;

import tools.jackson.databind.JsonNode;

/**
 * Collect-all structural validator. Verifies the OAS skeleton (openapi version,
 * info.title, info.version, paths) and walks the entire document collecting EVERY
 * error, in particular every unresolvable local $ref, before the caller decides.
 * This is the authoritative gate for policy rule 4; the Swagger Parser result is an
 * additional signal but never the only one.
 */
final class StructuralValidator {

    private static final int MAX_DEPTH = 500;

    private final JsonNode root;

    StructuralValidator(JsonNode root) {
        this.root = root;
    }

    List<SpecValidationError> validate() {
        List<SpecValidationError> errors = new ArrayList<>();

        JsonNode openapi = root.get("openapi");
        if (openapi == null || !openapi.isTextual()) {
            errors.add(new SpecValidationError("/openapi", "missing or not a string"));
        } else if (!openapi.textValue().startsWith("3.0")) {
            errors.add(new SpecValidationError("/openapi",
                    "unsupported OpenAPI version '" + openapi.textValue() + "' (only 3.0.x is accepted)"));
        }

        JsonNode info = root.get("info");
        if (info == null || !info.isObject()) {
            errors.add(new SpecValidationError("/info", "missing or not an object"));
        } else {
            JsonNode title = info.get("title");
            if (title == null || !title.isTextual() || title.textValue().isBlank()) {
                errors.add(new SpecValidationError("/info/title", "missing or blank"));
            }
            JsonNode version = info.get("version");
            if (version == null || !version.isTextual() || version.textValue().isBlank()) {
                errors.add(new SpecValidationError("/info/version", "missing or blank"));
            }
        }

        JsonNode paths = root.get("paths");
        if (paths == null || !paths.isObject()) {
            errors.add(new SpecValidationError("/paths", "missing or not an object"));
        }

        walk(root, "", 0, errors);
        return errors;
    }

    private void walk(JsonNode node, String pointer, int depth, List<SpecValidationError> errors) {
        if (depth > MAX_DEPTH) {
            errors.add(new SpecValidationError(pointer, "document nesting exceeds depth limit"));
            return;
        }
        if (node.isObject()) {
            JsonNode ref = node.get("$ref");
            if (ref != null && ref.isTextual()) {
                validateRef(ref.textValue(), pointer, errors);
                return; // a $ref sibling context is not walked further
            }
            Iterator<Map.Entry<String, JsonNode>> fields = node.fields();
            while (fields.hasNext()) {
                Map.Entry<String, JsonNode> field = fields.next();
                walk(field.getValue(), childPointer(pointer, field.getKey()), depth + 1, errors);
            }
        } else if (node.isArray()) {
            int index = 0;
            for (JsonNode element : node) {   // Iterable on ArrayNode
                walk(element, pointer + "/" + index++, depth + 1, errors);
            }
        }
    }

    private void validateRef(String ref, String pointer, List<SpecValidationError> errors) {
        if (ref.isBlank()) {
            errors.add(new SpecValidationError(pointer + "/$ref", "empty $ref"));
            return;
        }
        if (!RefResolver.isLocalRef(ref)) {
            errors.add(new SpecValidationError(pointer + "/$ref",
                    "non-local reference '" + ref + "' is not supported (only same-document #/ pointers)"));
            return;
        }
        if (!RefResolver.resolve(root, ref).isPresent()) {
            String name = ref.substring(ref.lastIndexOf('/') + 1);
            errors.add(new SpecValidationError(pointer + "/$ref",
                    "unresolved reference '" + ref + "': target does not exist (missing component '" + name + "')"));
        }
    }

    private static String childPointer(String pointer, String key) {
        // JSON Pointer escaping: ~ -> ~0, / -> ~1
        return pointer + "/" + key.replace("~", "~0").replace("/", "~1");
    }
}

package com.contractguard.specs;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

import tools.jackson.databind.JsonNode;

/**
 * Effective-schema extraction: for every wire location (method + path shape + scope)
 * produces a $ref-free, inline-expanded schema rendered as canonical JSON. Component
 * names and $ref placement disappear here, so quote v1.0.0 (named components, $refs)
 * and v1.1.0 (inlined objects, renamed components) produce IDENTICAL maps when their
 * wire contract is the same.
 *
 * Scopes: "requestBody", "param:<in>:<ordinal>" (one entry per parameter position, in
 * document order; path, query, header and cookie parameters are collected separately
 * per OAS grouping rules), "response:<status>", "responsesDefault" (components-free
 * default responses are keyed by their literal status only when present).
 */
final class EffectiveSchemaExtractor {

    private static final int MAX_EXPANSION_DEPTH = 50;

    private final JsonNode root;

    EffectiveSchemaExtractor(JsonNode root) {
        this.root = root;
    }

    Map<String, String> extract() {
        Map<String, String> out = new TreeMap<>();
        JsonNode paths = root.get("paths");
        if (paths == null || !paths.isObject()) {
            return out;
        }
        paths.fields().forEachRemaining(pathEntry -> {
            String rawPath = pathEntry.getKey();
            JsonNode pathItem = pathEntry.getValue();
            if (pathItem == null || !pathItem.isObject()) {
                return;
            }
            String pathShape = PathShapes.normalize(rawPath);
            // path-level parameters apply to every operation unless overridden
            List<JsonNode> pathLevelParams = parameterList(pathItem.get("parameters"));

            pathItem.fields().forEachRemaining(opEntry -> {
                String method = opEntry.getKey();
                if (!HttpMethods.isMethod(method)) {
                    return; // skips non-operation keys ("parameters", "$ref", "summary"...)
                }
                JsonNode operation = opEntry.getValue();
                if (operation == null || !operation.isObject()) {
                    return;
                }
                extractOperation(rawPath, pathShape, method, pathLevelParams, operation, out);
            });
        });
        return out;
    }

    private void extractOperation(String rawPath, String pathShape, String method,
                                  List<JsonNode> pathLevelParams, JsonNode operation,
                                  Map<String, String> out) {
        // --- parameters (operation-level override path-level per OAS semantics) ---
        List<JsonNode> opParams = parameterList(operation.get("parameters"));
        List<JsonNode> merged = mergeParameters(pathLevelParams, opParams);
        Map<String, Integer> counters = new TreeMap<>();
        for (JsonNode param : merged) {
            String in = text(param, "in");
            if (in == null) {
                continue;
            }
            if ("path".equals(in) && text(param, "name") != null
                    && !rawPath.contains("{" + text(param, "name") + "}")) {
                continue; // never emit params for placeholders the template does not have
            }
            String scope = "param:" + in + ":" + counters.merge(in, 1, Integer::sum);
            out.put(new EffectiveLocation(method, pathShape, scope).key(),
                    expand(param.get("schema") != null ? param.get("schema") : param));
        }

        // --- request body ---
        JsonNode requestBody = operation.get("requestBody");
        if (requestBody != null && requestBody.isObject()) {
            JsonNode content = requestBody.get("content");
            if (content != null && content.isObject()) {
                content.fields().forEachRemaining(mt -> {
                    JsonNode schema = mt.getValue() == null ? null : mt.getValue().get("schema");
                    String scope = "requestBody" + (mt.getKey() == null ? "" : ":" + mt.getKey());
                    out.put(new EffectiveLocation(method, pathShape, scope).key(),
                            schema == null ? "null" : expand(schema));
                });
            }
        }

        // --- responses ---
        JsonNode responses = operation.get("responses");
        if (responses != null && responses.isObject()) {
            responses.fields().forEachRemaining(resp -> {
                String status = resp.getKey();
                JsonNode response = resp.getValue();
                if (response == null || !response.isObject()) {
                    return;
                }
                JsonNode content = response.get("content");
                if (content != null && content.isObject()) {
                    content.fields().forEachRemaining(mt -> {
                        JsonNode schema = mt.getValue() == null ? null : mt.getValue().get("schema");
                        String scope = "response:" + status + (mt.getKey() == null ? "" : ":" + mt.getKey());
                        out.put(new EffectiveLocation(method, pathShape, scope).key(),
                                schema == null ? "null" : expand(schema));
                    });
                } else {
                    // documented status without a schema is still part of the wire contract
                    out.put(new EffectiveLocation(method, pathShape, "response:" + status).key(), "null");
                }
            });
        }
    }

    private List<JsonNode> parameterList(JsonNode parameters) {
        List<JsonNode> list = new ArrayList<>();
        if (parameters != null && parameters.isArray()) {
            for (JsonNode element : parameters) {
                if (element != null && element.isObject()) {
                    list.add(element);
                }
            }
        }
        return list;
    }

    /**
     * OAS rule: an operation-level parameter with the same (in, name) pair overrides a
     * path-level one; others are additive.
     */
    private List<JsonNode> mergeParameters(List<JsonNode> pathLevel, List<JsonNode> opLevel) {
        List<JsonNode> merged = new ArrayList<>(opLevel);
        for (JsonNode pathParam : pathLevel) {
            String in = text(pathParam, "in");
            String name = text(pathParam, "name");
            boolean overridden = false;
            for (JsonNode opParam : opLevel) {
                if (in != null && in.equals(text(opParam, "in")) && name != null
                        && name.equals(text(opParam, "name"))) {
                    overridden = true;
                    break;
                }
            }
            if (!overridden) {
                merged.add(pathParam);
            }
        }
        return merged;
    }

    /**
     * Inline-expands every local $ref (recursively, depth-guarded) and renders the
     * result as canonical JSON (sorted keys, sorted required arrays).
     */
    String expand(JsonNode schema) {
        JsonNode expanded = expandNode(schema, 0);
        Object canonical = CanonicalJson.canonicalize(expanded);
        return JsonMappers.writeCanonical(canonical);
    }

    private JsonNode expandNode(JsonNode node, int depth) {
        if (node == null || node.isMissingNode()) {
            return JsonMappers.missingNode();
        }
        if (depth > MAX_EXPANSION_DEPTH) {
            return node; // depth guard: kit has no cycles; over-deep docs pass through
        }
        if (node.isObject()) {
            JsonNode ref = node.get("$ref");
            if (ref != null && ref.isTextual() && RefResolver.isLocalRef(ref.textValue())) {
                java.util.Optional<JsonNode> target = RefResolver.resolve(root, ref.textValue());
                if (target.isEmpty()) {
                    // validator will have rejected the document; emit a marker
                    return JsonMappers.textNode("$unresolved:" + ref.textValue());
                }
                return expandNode(target.get(), depth + 1);
            }
            // objects with children that may contain $refs: expand schema-bearing keys
            java.util.TreeMap<String, JsonNode> out = new java.util.TreeMap<>();
            node.fields().forEachRemaining(entry -> {
                String key = entry.getKey();
                JsonNode value = entry.getValue();
                if (isSchemaContainer(key) && value != null && value.isObject()
                        && containsSchemaSemantics(key)) {
                    out.put(key, expandNode(value, depth + 1));
                } else if ("properties".equals(key) && value != null && value.isObject()) {
                    java.util.TreeMap<String, JsonNode> props = new java.util.TreeMap<>();
                    value.fields().forEachRemaining(p -> props.put(p.getKey(), expandNode(p.getValue(), depth + 1)));
                    out.put(key, JsonMappers.objectFrom(props));
                } else if ("items".equals(key) && value != null && value.isObject()) {
                    out.put(key, expandNode(value, depth + 1));
                } else if ("additionalProperties".equals(key) && value != null && value.isObject()) {
                    out.put(key, expandNode(value, depth + 1));
                } else if ("allOf".equals(key) || "anyOf".equals(key) || "oneOf".equals(key)) {
                    out.put(key, expandSchemaArray(value, depth));
                } else {
                    out.put(key, value);
                }
            });
            return JsonMappers.objectFrom(out);
        }
        return node;
    }

    private JsonNode expandSchemaArray(JsonNode arrayNode, int depth) {
        List<JsonNode> expanded = new ArrayList<>();
        for (JsonNode element : arrayNode) {
            expanded.add(expandNode(element, depth + 1));
        }
        return JsonMappers.arrayFrom(expanded);
    }

    private static boolean isSchemaContainer(String key) {
        return "schema".equals(key) || "items".equals(key) || "additionalProperties".equals(key);
    }

    private static boolean containsSchemaSemantics(String key) {
        // parameter nodes carry {name, in, schema}; only their "schema" child is expanded
        return true;
    }
}

package com.contractguard.specs;

import java.util.Set;

/**
 * HTTP methods recognized as operations in a Path Item (per OpenAPI: get, put, post,
 * delete, options, head, patch, trace). Everything else under /paths/{path} is a
 * Path Item Object field (parameters, summary, description, servers) and must not be
 * treated as an operation.
 */
final class HttpMethods {

    private static final Set<String> METHODS = Set.of(
            "get", "put", "post", "delete", "options", "head", "patch", "trace");

    private HttpMethods() {
    }

    static boolean isMethod(String key) {
        return key != null && METHODS.contains(key.toLowerCase());
    }
}

package com.contractguard.specs;

import java.util.List;
import java.util.Map;
import java.util.TreeMap;

import tools.jackson.databind.JsonNode;
import tools.jackson.databind.node.ArrayNode;
import tools.jackson.databind.node.JsonNodeFactory;
import tools.jackson.databind.node.ObjectNode;
import tools.jackson.databind.node.TextNode;

/**
 * Shared Jackson 3 helpers for building nodes and rendering canonical JSON.
 * Object keys are emitted in sorted order; maps written through this class therefore
 * produce stable, comparable strings.
 */
final class JsonMappers {

    private static final com.fasterxml.jackson.databind.ObjectMapper CANONICAL_JSON =
            new com.fasterxml.jackson.databind.ObjectMapper()
                    .registerModule(new com.fasterxml.jackson.databind.json.jsonMapper()
                            .serializationOrder()
                            .build());

    private JsonMappers() {
    }
}

package com.contractguard.specs;

import java.util.List;
import java.util.TreeMap;

import tools.jackson.databind.json.JsonMapper;
import tools.jackson.databind.node.ArrayNode;
import tools.jackson.databind.node.JsonNodeFactory;
import tools.jackson.databind.node.ObjectNode;
import tools.jackson.databind.node.TextNode;

/**
 * Shared Jackson 3 helpers for building nodes and rendering canonical JSON.
 *
 * Canonical JSON is always rendered from the plain Map/List structures produced by
 * {@link CanonicalJson} (TreeMap-backed, sorted) or from TreeMap-ordered ObjectNodes,
 * so equal structures always serialize to equal strings regardless of input key order.
 */
final class JsonMappers {

    private static final JsonMapper CANONICAL = JsonMapper.builder().build();

    private JsonMappers() {
    }

    /** Serializes a canonical Map/List (or any JSON-serializable value) deterministically. */
    static String writeCanonical(Object value) {
        return CANONICAL.writeValueAsString(value);
    }

