        ObjectNode out = JsonNodeFactory.instance.objectNode();
        source.forEach((key, value) -> out.set(key, asNode(value)));
        return out;
    }

    /** Builds an ArrayNode preserving element order. */
    static ArrayNode arrayFrom(List<?> values) {
        ArrayNode out = JsonNodeFactory.instance.arrayNode();
        for (Object value : values) {
            out.add(asNode(value));
        }
        return out;
    }

    static TextNode textNode(String value) {
        return JsonNodeFactory.instance.textNode(value);
    }

    static <T extends tools.jackson.databind.JsonNode> T asNode(Object value) {
        if (value instanceof tools.jackson.databind.JsonNode node) {
            @SuppressWarnings("unchecked")
            T cast = (T) node;
            return cast;
        }
        return CANONICAL.valueToTree(value);
    }
}

