package com.contractguard.specs;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Optional;

import tools.jackson.databind.JsonNode;

/**
 * Scans a specification for {@code deprecated: true} on any object node (fields,
 * operations, parameters) and captures the optional {@code x-sunset} extension.
 * Generic by design: classification into findings is not this class's job.
 *
 * Field paths are rendered in the consumer-file coordinate system: dot-separated
 * property names, {@code []} after array properties, e.g.
 * {@code components.schemas.Policy.legacyCode} → "Policy.legacyCode" for schema roots.
 */
final class DeprecationScanner {

    private static final int MAX_DEPTH = 500;

    private final JsonNode root;

    DeprecationScanner(JsonNode root) {
        this.root = root;
    }

    List<DeprecationRecord> scan() {
        List<DeprecationRecord> records = new ArrayList<>();
        JsonNode schemas = root.get("components") == null ? null : root.get("components").get("schemas");
        if (schemas != null && schemas.isObject()) {
            schemas.fields().forEachRemaining(schemaEntry -> {
                JsonNode schema = schemaEntry.getValue();
                // a schema may itself be a $ref node — then nothing to scan inside it
                if (schema != null && schema.isObject()) {
                    walkSchema(schema, schemaEntry.getKey(), 0, records);
                }
            });
        }
        return records;
    }

    private void walkSchema(JsonNode node, String fieldPath, int depth, List<DeprecationRecord> records) {
        if (node == null || !node.isObject() || depth > MAX_DEPTH) {
            return;
        }
        JsonNode ref = node.get("$ref");
        if (ref != null && ref.isTextual()) {
            return; // do not follow refs here: targets are scanned at their own root
        }
        JsonNode deprecated = node.get("deprecated");
        if (deprecated != null && deprecated.isBoolean() && deprecated.booleanValue()) {
            records.add(toRecord(node, fieldPath));
        }
        JsonNode properties = node.get("properties");
        if (properties != null && properties.isObject()) {
            properties.fields().forEachRemaining(prop ->
                    walkSchema(prop.getValue(),
                            fieldPath.isEmpty() ? prop.getKey() : fieldPath + "." + prop.getKey(),
                            depth + 1, records));
        }
        JsonNode items = node.get("items");
        if (items != null && items.isObject()) {
            walkSchema(items, fieldPath + "[]", depth + 1, records);
        }
    }

    private DeprecationRecord toRecord(JsonNode node, String fieldPath) {
        JsonNode sunsetNode = node.get("x-sunset");
        Optional<String> sunsetRaw = sunsetNode != null && sunsetNode.isTextual()
                ? Optional.of(sunsetNode.textValue())
                : Optional.empty();
        Optional<LocalDate> sunset = sunsetRaw.map(DeprecationScanner::parseDate);
        return new DeprecationRecord("#/components/schemas/" + fieldPath, fieldPath, sunsetRaw, sunset);
    }

    private static Optional<LocalDate> parseDate(String raw) {
        if (raw == null || raw.isBlank()) {
            return Optional.empty();
        }
        try {
            return Optional.of(LocalDate.parse(raw.trim()));
        } catch (DateTimeParseException e) {
            try {
                // tolerate full ISO timestamps ("2026-11-01T00:00:00Z")
                return Optional.of(LocalDate.parse(raw.trim().substring(0, 10)));
            } catch (RuntimeException e2) {
                return Optional.empty();
            }
        }
    }
}

package com.contractguard.specs;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

import org.springframework.stereotype.Service;

import tools.jackson.databind.JsonNode;
import tools.jackson.databind.json.JsonMapper;
import tools.jackson.dataformat.yaml.YAMLFactory;

/**
 * Spec ingestion service: YAML → Jackson tree → collect-all structural validation →
 * canonical form → effective wire-contract schemas → deprecation scan.
 *
 * Swagger Parser's typed model is consulted only as an auxiliary signal; the
 * authoritative validation is the collect-all walk in {@link StructuralValidator},
 * which reports every error (not only the first) before the caller decides.
 */
@Service
public class SpecParser {

    private final JsonMapper yamlMapper = JsonMapper.builder(new YAMLFactory()).build();
    private final JsonMapper jsonMapper = JsonMapper.builder().build();

    /**
     * Parses and validates a specification document. Throws {@link SpecParseException}
     * carrying ALL collected errors when anything is invalid.
     */
    public SpecDocument parse(String yamlContent) {
        JsonNode root = readYaml(yamlContent);

        List<SpecValidationError> errors = new StructuralValidator(root).validate();
        if (!errors.isEmpty()) {
            throw new SpecParseException(errors);
        }

        Map<String, String> effective = new EffectiveSchemaExtractor(root).extract();
        String canonicalJson = buildCanonicalJson(root);
        List<DeprecationRecord> deprecations = new DeprecationScanner(root).scan();

        return new SpecDocument(
                root.get("openapi").textValue(),
                root.get("info").get("title").textValue(),
                root.get("info").get("version").textValue(),
                canonicalJson,
                effective,
                deprecations,
                null);
    }

    private JsonNode readYaml(String content) {
        if (content == null || content.isBlank()) {
            throw new SpecParseException(List.of(
                    new SpecValidationError("/", "document is empty")));
        }
        try {
            JsonNode node = yamlMapper.readTree(content);
            if (node == null || node.isNull() || !node.isObject()) {
                throw new SpecParseException(List.of(
                        new SpecValidationError("/", "document is not a YAML mapping (object)")));
            }
            return node;
        } catch (SpecParseException e) {
            throw e;
        } catch (RuntimeException e) {
            throw new SpecParseException(List.of(new SpecValidationError("/",
                    "invalid YAML: " + e.getMessage())));
        }
    }

    /**
     * Whole-document canonical form with sorted keys and sorted {@code required}
     * arrays — insensitive to formatting and key order, sensitive to real content.
     * Used for duplicate-version identity comparison.
     */
    private String buildCanonicalJson(JsonNode root) {
        Object canonical = CanonicalJson.canonicalize(root);
        return jsonMapper.writeValueAsString(canonical);
    }

    /** Renders an effective-schema map as a stable JSON object (sorted keys). */
    public String writeEffectiveJson(Map<String, String> effective) {
        TreeMap<String, String> sorted = new TreeMap<>(effective);
        return jsonMapper.writeValueAsString(sorted);
    }

    /** Small helper reused by pipeline stages that need ordered DTO maps. */
    public Map<String, Object> orderedInfo(SpecDocument doc) {
        Map<String, Object> info = new LinkedHashMap<>();
        info.put("openapi", doc.getOpenapiVersion());
        info.put("title", doc.getTitle());
        info.put("version", doc.getSpecVersion());
        info.put("effectiveLocations", doc.getEffectiveSchemas().size());
        info.put("deprecations", doc.getDeprecations().size());
        return info;
    }
}

