package com.contractguard.specs;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;

/**
 * Test helper: reads the read-only starter-kit fixtures from the repository root
 * (Maven surefire runs with the module directory as the working directory). Fixtures
 * are never modified by tests.
 */
final class Fixtures {

    private Fixtures() {
    }

    static String spec(String service, String file) {
        return read(Path.of("specs", service, file));
    }

    static String consumer(String file) {
        return read(Path.of("consumers", file));
    }

    private static String read(Path path) {
        try {
            return Files.readString(path);
        } catch (IOException e) {
            throw new IllegalStateException("cannot read fixture " + path + " — run tests from the repository root", e);
        }
    }
}

package com.contractguard.specs;

import static org.assertj.core.api.Assertions.assertThat;

import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInstance;

/**
 * Parses the actual quote API v1.0.0 fixture (without reference to its filename —
 * the file is loaded by path and all assertions are content-derived).
 */
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class SpecParserQuoteV1Test {

    private SpecDocument doc;

    @BeforeAll
    void parseActualQuoteV1() {
        doc = new SpecParser().parse(Fixtures.spec("quote-api", "1-initial.yaml"));
    }

    @Test
    @DisplayName("quote v1.0.0: metadata is read from content")
    void metadata() {
        assertThat(doc.getOpenapiVersion()).isEqualTo("3.0.3");
        assertThat(doc.getTitle()).isEqualTo("Quote API");
        assertThat(doc.getSpecVersion()).isEqualTo("1.0.0");
    }

    @Test
    @DisplayName("quote v1.0.0: effective map has one location per wire contract point")
    void effectiveLocations() {
        var keys = doc.getEffectiveSchemas().keySet();
        assertThat(keys).contains(
                "POST /quotes :: requestBody:application/json",
                "POST /quotes :: response:201:application/json",
                "POST /quotes :: response:400",
                "GET /quotes/{0} :: param:path:1",
                "GET /quotes/{0} :: response:200:application/json",
                "GET /quotes/{0} :: response:404",
                "DELETE /internal/pricing-cache :: response:204");
        assertThat(keys).hasSize(7);
    }

    @Test
    @DisplayName("quote v1.0.0: $refs are inline-expanded into the effective request schema")
    void requestBodyIsExpanded() {
        String body = doc.getEffectiveSchemas().get("POST /quotes :: requestBody:application/json");
        assertThat(body).contains("\"vehicle\"");
        assertThat(body).contains("\"cc\"");
        // expansion must have erased the component name
        assertThat(body).doesNotContain("Vehicle");
        assertThat(body).doesNotContain("$ref");
        // nested required lists survive, sorted
        assertThat(body).contains("\"required\":[\"make\",\"cc\"]");
    }

    @Test
    @DisplayName("quote v1.0.0: response schema is the expanded Quote shape")
    void responseShape() {
        String response = doc.getEffectiveSchemas().get("POST /quotes :: response:201:application/json");
        assertThat(response).contains("\"quoteId\"");
        assertThat(response).contains("\"DRAFT\"");
        assertThat(response).contains("\"breakdown\"");
        assertThat(response).contains("\"amount\"");
        assertThat(response).doesNotContain("Premium\"");
        assertThat(response).doesNotContain("$ref");
    }

    @Test
    @DisplayName("quote v1.0.0: status-only responses are recorded as schema-less")
    void schemalessResponses() {
        assertThat(doc.getEffectiveSchemas().get("POST /quotes :: response:400")).isEqualTo("null");
        assertThat(doc.getEffectiveSchemas().get("DELETE /internal/pricing-cache :: response:204")).isEqualTo("null");
    }

    @Test
    @DisplayName("quote v1.0.0: x-internal operation is present with no parameters")
    void internalOperation() {
        var keys = doc.getEffectiveSchemas().keySet();
        assertThat(keys.stream().filter(k -> k.startsWith("DELETE /internal/pricing-cache"))).hasSize(1);
    }

    @Test
    @DisplayName("quote v1.0.0: no deprecated fields")
    void noDeprecations() {
        assertThat(doc.getDeprecations()).isEmpty();
    }
}

package com.contractguard.specs;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.Map;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

/**
 * The starter kit's deliberate trap: quote v1.0.0 → v1.1.0 renames components
 * (Premium→PremiumDetails, BreakdownItem→PriceLine), inlines Vehicle/Rider into
 * QuoteRequest and renames the path parameter {id}→{quoteId}. The wire contract does
 * not change, so the effective-schema maps must be EQUAL while the whole-document
 * canonical forms must DIFFER (the documents are genuinely different).
 */
class CosmeticEquivalenceTest {

    private final SpecParser parser = new SpecParser();

    @Test
    @DisplayName("quote v1.0.0 and v1.1.0 have equivalent effective wire contracts")
    void effectiveContractsAreEquivalent() {
        Map<String, String> v1 = parser.parse(Fixtures.spec("quote-api", "1-initial.yaml")).getEffectiveSchemas();
        Map<String, String> v11 = parser.parse(Fixtures.spec("quote-api", "2-reorganised.yaml")).getEffectiveSchemas();

        assertThat(v11.keySet()).isEqualTo(v1.keySet());
        for (String key : v1.keySet()) {
            assertThat(v11.get(key))
                    .as("effective schema for %s must be identical after cosmetic reorg", key)
                    .isEqualTo(v1.get(key));
        }
    }

    @Test
    @DisplayName("canonical whole-document forms differ (content really changed)")
    void canonicalFormsDiffer() {
        String v1 = parser.parse(Fixtures.spec("quote-api", "1-initial.yaml")).getCanonicalJson();
        String v11 = parser.parse(Fixtures.spec("quote-api", "2-reorganised.yaml")).getCanonicalJson();
        assertThat(v11).isNotEqualTo(v1);
    }

    @Test
    @DisplayName("genuinely different versions do not collapse to the same effective map")
    void realChangesAreVisible() {
        Map<String, String> v2 = parser.parse(Fixtures.spec("quote-api", "3-price-lines.yaml")).getEffectiveSchemas();
        Map<String, String> v11 = parser.parse(Fixtures.spec("quote-api", "2-reorganised.yaml")).getEffectiveSchemas();
        // v2 renames breakdown[].amount → value and adds EXPIRED: maps must differ
        assertThat(v2).isNotEqualTo(v11);
    }

    @Test
    @DisplayName("synthetic: inline object and $ref with identical shape are equivalent")
    void syntheticInlineVsRef() {
        String withRef = """
                openapi: 3.0.3
                info: {title: T, version: 1.0.0}
                paths:
                  /things:
                    post:
                      responses:
                        '200':
                          description: ok
                          content:
                            application/json:
                              schema:
                                $ref: '#/components/schemas/Thing'
                components:
                  schemas:
                    Thing:
                      type: object
                      required: [a]
                      properties:
                        a: {type: string}
                """;
        String inlined = """
                openapi: 3.0.3
                info: {title: T, version: 1.0.0}
                paths:
                  /things:
                    post:
                      responses:
                        '200':
                          description: ok
                          content:
                            application/json:
                              schema:
                                type: object
                                required: [a]
                                properties:
                                  a: {type: string}
                """;
        var a = parser.parse(withRef).getEffectiveSchemas();
        var b = parser.parse(inlined).getEffectiveSchemas();
        assertThat(b).isEqualTo(a);
    }

    @Test
    @DisplayName("synthetic: required-array order is irrelevant to equivalence")
    void syntheticRequiredOrderIrrelevant() {
        String docA = """
                openapi: 3.0.3
                info: {title: T, version: 1.0.0}
                paths:
                  /x:
                    post:
                      requestBody:
                        content:
                          application/json:
                            schema:
                              type: object
                              required: [b, a]
                              properties:
                                a: {type: string}
                                b: {type: string}
                      responses: {'200': {description: ok}}
                """;
        String docB = docA.replace("required: [b, a]", "required: [a, b]");
        assertThat(parser.parse(docB).getEffectiveSchemas())
                .isEqualTo(parser.parse(docA).getEffectiveSchemas());
    }
}

package com.contractguard.specs;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.util.List;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

/**
 * Policy rule 4: invalid specifications (including unresolved $refs) are rejected with
 * ALL collected errors. Uses the actual broken claims fixture plus filename-independent
 * synthetic documents.
 */
class BrokenSpecRejectionTest {

    private final SpecParser parser = new SpecParser();

    @Test
    @DisplayName("claims v1.1.0 (broken $ref) is rejected and names the missing component")
    void brokenClaimsRefIsRejected() {
        String broken = Fixtures.spec("claims-api", "2-channel-and-notes.yaml");

        assertThatThrownBy(() -> parser.parse(broken))
                .isInstanceOf(SpecParseException.class)
                .satisfies(e -> {
                    SpecParseException spe = (SpecParseException) e;
                    List<SpecValidationError> errors = spe.getErrors();
                    assertThat(errors).isNotEmpty();
                    assertThat(errors).anyMatch(err ->
                            err.message().contains("ClaimDocumnt")
                                    && err.message().contains("unresolved reference"));
                    // the pointer pinpoints the offending node
                    assertThat(errors).anyMatch(err ->
                            err.pointer().contains("/components/schemas/Claim/properties/documents"));
                });
    }

    @Test
    @DisplayName("corrected claims v1.1.0 is accepted")
    void correctedClaimsIsAccepted() {
        SpecDocument doc = parser.parse(Fixtures.spec("claims-api", "3-channel-and-notes-fixed.yaml"));
        assertThat(doc.getTitle()).isEqualTo("Claims API");
        assertThat(doc.getSpecVersion()).isEqualTo("1.1.0");
        assertThat(doc.getDeprecations()).isEmpty();
        // documents the new optional fields of 1.1.0
        String body = doc.getEffectiveSchemas().get("POST /claims :: requestBody:application/json");
        assertThat(body).contains("channel");
        String claim = doc.getEffectiveSchemas().get("GET /claims/{0} :: response:200:application/json");
        assertThat(claim).contains("assessorNotes");
        assertThat(claim).contains("ClaimDocument".substring(0, 0) + "docId"); // content, not name
        assertThat(claim).doesNotContain("ClaimDocumnt\"");
    }

    @Test
    @DisplayName("synthetic: unresolved ref is rejected with a precise pointer")
    void syntheticUnresolvedRef() {
        String yaml = """
                openapi: 3.0.3
                info: {title: T, version: 1.0.0}
                paths:
                  /a:
                    get:
                      responses:
                        '200':
                          description: ok
                          content:
                            application/json:
                              schema:
                                $ref: '#/components/schemas/Missing'
                components:
                  schemas:
                    Other: {type: string}
                """;
        assertThatThrownBy(() -> parser.parse(yaml))
                .isInstanceOf(SpecParseException.class)
                .satisfies(e -> {
                    List<SpecValidationError> errors = ((SpecParseException) e).getErrors();
                    assertThat(errors).hasSize(1);
                    assertThat(errors.get(0).message()).contains("Missing");
                    assertThat(errors.get(0).pointer())
                            .isEqualTo("/paths/~1a/get/responses/200/content/application~1json/schema/$ref");
                });
    }

    @Test
    @DisplayName("synthetic: ALL errors are collected, not just the first")
    void collectsAllErrors() {
        String yaml = """
                openapi: 3.0.3
                info: {title: T, version: 1.0.0}
                paths:
                  /a:
                    get:
                      responses:
                        '200':
                          description: ok
                          content:
                            application/json:
                              schema:
                                $ref: '#/components/schemas/M1'
                  /b:
                    post:
                      requestBody:
                        content:
                          application/json:
                            schema:
                              $ref: '#/components/schemas/M2'
                      responses: {'200': {description: ok}}
                components:
                  schemas: {}
                """;
        assertThatThrownBy(() -> parser.parse(yaml))
                .isInstanceOf(SpecParseException.class)
                .satisfies(e -> {
                    List<SpecValidationError> errors = ((SpecParseException) e).getErrors();
                    assertThat(errors).hasSize(2);
                    assertThat(errors).anyMatch(err -> err.message().contains("M1"));
                    assertThat(errors).anyMatch(err -> err.message().contains("M2"));
                });
    }

    @Test
    @DisplayName("synthetic: non-local refs are rejected")
    void nonLocalRefRejected() {
        String yaml = """
                openapi: 3.0.3
                info: {title: T, version: 1.0.0}
                paths:
                  /a:
                    get:
                      responses:
                        '200':
                          description: ok
                          content:
                            application/json:
                              schema:
                                $ref: 'https://other.host/schemas/Thing.yaml'
                """;
        assertThatThrownBy(() -> parser.parse(yaml))
                .isInstanceOf(SpecParseException.class)
                .satisfies(e -> {
                    List<SpecValidationError> errors = ((SpecParseException) e).getErrors();
                    assertThat(errors).anyMatch(err -> err.message().contains("non-local reference"));
                });
    }

    @Test
    @DisplayName("synthetic: skeleton violations (missing info.version) are rejected")
    void missingVersionRejected() {
        String yaml = """
                openapi: 3.0.3
                info: {title: T}
                paths:
                  /a: {get: {responses: {'200': {description: ok}}}}
                """;
        assertThatThrownBy(() -> parser.parse(yaml))
                .isInstanceOf(SpecParseException.class)
                .satisfies(e -> {
                    List<SpecValidationError> errors = ((SpecParseException) e).getErrors();
                    assertThat(errors).anyMatch(err -> err.pointer().equals("/info/version"));
                });
    }

    @Test
    @DisplayName("synthetic: malformed YAML is rejected cleanly")
    void malformedYamlRejected() {
        assertThatThrownBy(() -> parser.parse("{{{{ not yaml"))
                .isInstanceOf(SpecParseException.class)
                .satisfies(e -> assertThat(((SpecParseException) e).getErrors()).isNotEmpty());

        assertThatThrownBy(() -> parser.parse("   "))
                .isInstanceOf(SpecParseException.class)
                .satisfies(e -> assertThat(((SpecParseException) e).getErrors()).anyMatch(
                        err -> err.message().contains("empty")));
    }
}

package com.contractguard.specs;

import static org.assertj.core.api.Assertions.assertThat;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

class PathShapesTest {

    @Test
    @DisplayName("placeholder names are ignored; positions are kept")
    void placeholderNamesIgnored() {
        assertThat(PathShapes.normalize("/quotes/{id}")).isEqualTo("/quotes/{0}");
        assertThat(PathShapes.normalize("/quotes/{quoteId}")).isEqualTo("/quotes/{0}");
    }

    @Test
    @DisplayName("different shapes never collide")
    void differentShapesDiffer() {
        assertThat(PathShapes.normalize("/policies/{policyId}"))
                .isNotEqualTo(PathShapes.normalize("/policies/{policyId}/endorsements"));
        assertThat(PathShapes.normalize("/policies/{a}/endorsements/{b}"))
                .isEqualTo(PathShapes.normalize("/policies/{x}/endorsements/{y}"));
    }

    @Test
    @DisplayName("literal segments are case- and slash-normalized")
    void literalsPreserved() {
        assertThat(PathShapes.normalize("quotes/{id}")).isEqualTo("/quotes/{0}");
        assertThat(PathShapes.normalize("/a//b/{c}/")).isEqualTo("/a/b/{0}");
        assertThat(PathShapes.normalize("/")).isEqualTo("/");
        assertThat(PathShapes.normalize(null)).isEqualTo("/");
    }

    @Test
    @DisplayName("curly braces inside literals are not placeholders")
    void onlyWholeSegmentPlaceholders() {
        assertThat(PathShapes.normalize("/files/{name}.txt")).isEqualTo("/files/{name}.txt");
        assertThat(PathShapes.normalize("/files/{name}")).isEqualTo("/files/{0}");
    }
}

package com.contractguard.specs;

import static org.assertj.core.api.Assertions.assertThat;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

/**
 * Deprecation/x-sunset scanning against the actual policy fixtures (which carry the
 * kit's planted lifecycle data) plus synthetic cases.
 */
class DeprecationScannerTest {

    private final SpecParser parser = new SpecParser();

    @Test
    @DisplayName("policy v1.1.0: deprecated fields found with parsed x-sunset dates")
    void policyDeprecationsFound() {
        SpecDocument doc = parser.parse(Fixtures.spec("policy-api", "2-deprecations.yaml"));
        assertThat(doc.getDeprecations()).hasSize(2);

        var byPath = doc.getDeprecations().stream()
                .collect(java.util.stream.Collectors.toMap(DeprecationRecord::humanPath, r -> r));

        assertThat(byPath).containsKeys("Policy.legacyCode", "Holder.phone");

        assertThat(byPath.get("Policy.legacyCode").sunset()).contains(java.time.LocalDate.parse("2026-11-01"));
        assertThat(byPath.get("Policy.legacyCode").sunsetRaw()).contains("2026-11-01");

        assertThat(byPath.get("Holder.phone").sunset()).contains(java.time.LocalDate.parse("2027-06-30"));
    }

    @Test
    @DisplayName("policy v1.0.0: nothing deprecated")
    void policyV1Clean() {
        SpecDocument doc = parser.parse(Fixtures.spec("policy-api", "1-initial.yaml"));
        assertThat(doc.getDeprecations()).isEmpty();
    }

    @Test
    @DisplayName("synthetic: deprecated flag without x-sunset is recorded with empty date")
    void deprecatedWithoutSunset() {
        String yaml = """
                openapi: 3.0.3
                info: {title: T, version: 1.0.0}
                paths: {}
                components:
                  schemas:
                    Thing:
                      type: object
                      properties:
                        old:
                          type: string
                          deprecated: true
                """;
        var records = parser.parse(yaml).getDeprecations();
        assertThat(records).hasSize(1);
        assertThat(records.get(0).humanPath()).isEqualTo("Thing.old");
        assertThat(records.get(0).sunset()).isEmpty();
        assertThat(records.get(0).sunsetRaw()).isEmpty();
    }

    @Test
    @DisplayName("synthetic: deprecated item inside an array renders [] field path")
    void deprecatedInsideArray() {
        String yaml = """
                openapi: 3.0.3
                info: {title: T, version: 1.0.0}
                paths: {}
                components:
                  schemas:
                    Line:
                      type: object
                      required: [label]
                      properties:
                        label: {type: string}
                    Bundle:
                      type: object
                      properties:
                        lines:
                          type: array
                          items:
                            type: object
                            properties:
                              note:
                                type: string
                                deprecated: true
                """;
        var records = parser.parse(yaml).getDeprecations();
        assertThat(records).hasSize(1);
        assertThat(records.get(0).humanPath()).isEqualTo("Bundle.lines[].note");
    }

    @Test
    @DisplayName("synthetic: malformed x-sunset dates do not crash scanning")
    void malformedSunsetTolerated() {
        String yaml = """
                openapi: 3.0.3
                info: {title: T, version: 1.0.0}
                paths: {}
                components:
                  schemas:
                    Thing:
                      type: object
                      properties:
                        old:
                          type: string
                          deprecated: true
                          x-sunset: 'not-a-date'
                """;
        var records = parser.parse(yaml).getDeprecations();
        assertThat(records).hasSize(1);
        assertThat(records.get(0).sunset()).isEmpty();
        assertThat(records.get(0).sunsetRaw()).contains("not-a-date");
    }
}

