17:     public static String normalize(String rawPath) {
18:         if (rawPath == null || rawPath.isBlank()) {
19:             return "/";
20:         }
21:         String trimmed = rawPath.trim();
22:         if (!trimmed.startsWith("/")) {
23:             trimmed = "/" + trimmed;
24:         }
25:         String[] segments = trimmed.split("/", -1);
26:         List<String> out = new ArrayList<>();
27:         int ordinal = 0;
28:         for (String segment : segments) {
29:             if (segment.isEmpty()) {
30:                 continue; // leading slash; consecutive slashes collapse
31:             }
32:             if (segment.startsWith("{") && segment.endsWith("}") && segment.length() >= 2) {
33:                 out.add("{" + ordinal++ + "}");
34:             } else {
35:                 out.add(segment);
36:             }
37:         }
38:         return "/" + String.join("/", out);
39:     }
