package com.contractguard.impact;

import com.contractguard.consumers.ConsumerDeclaration;
import com.contractguard.consumers.ConsumerRegistry;
import com.contractguard.specs.SpecDocument;
import com.contractguard.specs.SpecParser;
import org.springframework.stereotype.Service;

import java.util.List;

/**
 * Pipeline splice: parse two spec versions → diff (compatibility engine) → classify
 * consumer impact (registry × findings). The returned {@link ImpactReport} is the
 * unit the publishing-policy milestone will consume: findings for the gate rules,
 * the impact summary for the "breaking with affected consumers" condition.
 *
 * Pure computation — no persistence, no state changes (that is the publishing
 * workflow's job in a later milestone).
 */
@Service
public class ImpactService {

    private final SpecParser specParser;
    private final com.contractguard.compatibility.CompatibilityEngine compatibilityEngine
            = new com.contractguard.compatibility.CompatibilityEngine();
    private final ConsumerImpactAnalyzer impactAnalyzer = new ConsumerImpactAnalyzer();
    private final ConsumerRegistry consumerRegistry;

    public ImpactService(SpecParser specParser, ConsumerRegistry consumerRegistry) {
        this.specParser = specParser;
        this.consumerRegistry = consumerRegistry;
    }

    /**
     * @param service provider service slug as used in consumer files (e.g. "quote-api")
     * @param oldYaml currently published spec YAML
     * @param newYaml candidate spec YAML
     */
    public ImpactReport compare(String service, String oldYaml, String newYaml) {
        SpecDocument oldDoc = specParser.parse(oldYaml);
        SpecDocument newDoc = specParser.parse(newYaml);

        List<com.contractguard.compatibility.CompatibilityFinding> findings =
                compatibilityEngine.diff(oldDoc.getEffectiveSchemas(), newDoc.getEffectiveSchemas(),
                        oldDoc.getPathAliases(), newDoc.getPathAliases());

        List<ConsumerDeclaration> consumers = consumerRegistry.all();
        ImpactSummary summary = impactAnalyzer.analyze(service, oldDoc, newDoc, findings, consumers);

        return new ImpactReport(service, oldDoc.getSpecVersion(), newDoc.getSpecVersion(),
                findings, summary);
    }
}

package com.contractguard.impact;

import java.util.List;

/**
 * Full result of one candidate version transition: the compatibility findings and the
 * consumer impact rollup in one payload, keyed by service and the two versions.
 */
public record ImpactReport(String service, String oldVersion, String newVersion,
                           List<com.contractguard.compatibility.CompatibilityFinding> findings,
                           ImpactSummary summary) {

    public ImpactReport {
        findings = List.copyOf(findings);
    }
}

package com.contractguard.api;

import java.util.List;
import java.util.Map;

import com.contractguard.consumers.ConsumerDeclaration;
import com.contractguard.consumers.ConsumerParseException;
import com.contractguard.consumers.ConsumerRegistry;
import com.contractguard.consumers.DeclaredOperation;
import com.contractguard.impact.ImpactReport;
import com.contractguard.impact.ImpactService;
import com.contractguard.specs.SpecParseException;
import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

/**
 * Read-side API for the consumer registry and consumer impact. Impact computation is
 * a dry-run: it never persists state or notifies anyone (the publishing workflow,
 * built on top of {@link ImpactReport}, arrives in the next milestone).
 */
@RestController
@RequestMapping("/api")
public class ImpactController {

    private final ImpactService impactService;
    private final ConsumerRegistry consumerRegistry;

    public ImpactController(ImpactService impactService, ConsumerRegistry consumerRegistry) {
        this.impactService = impactService;
        this.consumerRegistry = consumerRegistry;
    }

    /** Registered consumers with their declared bindings. */
    @GetMapping("/consumers")
    public List<Map<String, Object>> consumers() {
        return consumerRegistry.all().stream().map(ImpactController::consumerView).toList();
    }

    /**
     * Consumer impact for a candidate version transition. {@code service} is the
     * provider slug used in consumer files (e.g. "quote-api"); both specs are supplied
     * as YAML text (the registry/persistence milestone will resolve them by version).
     */
    @PostMapping("/impact")
    public ImpactReport impact(@Valid @RequestBody ImpactRequest request) {
        return impactService.compare(request.service().trim(), request.oldSpec(), request.newSpec());
    }

    private static Map<String, Object> consumerView(ConsumerDeclaration consumer) {
        return Map.of(
                "consumer", consumer.name(),
                "team", consumer.team(),
                "operations", consumer.operations().stream()
                        .map(ImpactController::operationView)
                        .toList());
    }

    private static Map<String, Object> operationView(DeclaredOperation op) {
        return Map.of(
                "provider", op.provider(),
                "method", op.method(),
                "path", op.rawPath(),
                "sends", op.sends(),
                "reads", op.reads());
    }

    /** Request body of POST /api/impact. */
    public record ImpactRequest(@NotBlank String service,
                                @NotBlank String oldSpec,
                                @NotBlank String newSpec) {
    }

    @ExceptionHandler({SpecParseException.class, ConsumerParseException.class})
    @ResponseStatus(HttpStatus.BAD_REQUEST)
    public ResponseEntity<Map<String, String>> badSpec(RuntimeException e) {
        return ResponseEntity.badRequest().body(Map.of("error", e.getMessage()));
    }
}

