package com.contractguard.consumers;

import java.util.List;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import com.contractguard.specs.Fixtures;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/**
 * Consumer YAML parsing against the REAL kit fixture files (read-only) plus focused
 * error cases. Identity (consumer name, provider slug) must be preserved verbatim;
 * the only normalization allowed is method casing and path-shape normalization.
 */
class ConsumerParserTest {

    private final ConsumerParser parser = new ConsumerParser();

    @Test
    @DisplayName("mobile-app: identity, four bindings, sends/reads preserved verbatim")
    void parsesMobileApp() {
        ConsumerDeclaration c = parser.parse(Fixtures.consumer("mobile-app.yaml"));
        assertThat(c.name()).isEqualTo("mobile-app");
        assertThat(c.team()).isEqualTo("Mobile");
        assertThat(c.operations()).hasSize(4);

        DeclaredOperation postQuotes = c.operations().get(0);
        assertThat(postQuotes.provider()).isEqualTo("quote-api");
        assertThat(postQuotes.method()).isEqualTo("POST");
        assertThat(postQuotes.rawPath()).isEqualTo("/quotes");
        assertThat(postQuotes.sends()).containsExactly("vehicle.make", "vehicle.cc", "rider.age");
        assertThat(postQuotes.reads()).containsExactly("quoteId", "status", "premium.total",
                "premium.breakdown[].label", "premium.breakdown[].amount");

        // GET binding: the path template uses {id} while the spec uses {quoteId} — the
        // shape must normalize so they join; 'id' stays in sends (parameter usage)
        DeclaredOperation getQuote = c.operations().get(1);
        assertThat(getQuote.rawPath()).isEqualTo("/quotes/{id}");
        assertThat(getQuote.pathShape()).isEqualTo("/quotes/{0}");
        assertThat(getQuote.sends()).containsExactly("id");
        assertThat(getQuote.reads()).containsExactly("quoteId", "status", "premium.total");
    }

    @Test
    @DisplayName("partner-portal / payments-svc / notifications-svc: all parse with identity intact")
    void parsesRemainingKits() {
        ConsumerDeclaration partner = parser.parse(Fixtures.consumer("partner-portal.yaml"));
        assertThat(partner.name()).isEqualTo("partner-portal");
        assertThat(partner.team()).isEqualTo("Partner Integrations");
        assertThat(partner.forProvider("policy-api")).hasSize(1);
        assertThat(partner.forProvider("policy-api").get(0).rawPath())
                .isEqualTo("/policies/{policyId}/endorsements");
        assertThat(partner.forProvider("policy-api").get(0).sends())
                .containsExactly("policyId", "type", "details");

        ConsumerDeclaration payments = parser.parse(Fixtures.consumer("payments-svc.yaml"));
        assertThat(payments.name()).isEqualTo("payments-svc");
        assertThat(payments.forProvider("policy-api").get(0).reads())
                .contains("legacyCode", "premiumDue.amount", "premiumDue.dueDate");

        ConsumerDeclaration notifications = parser.parse(Fixtures.consumer("notifications-svc.yaml"));
        assertThat(notifications.name()).isEqualTo("notifications-svc");
        assertThat(notifications.operations()).hasSize(3);
        assertThat(notifications.forProvider("claims-api").get(0).reads())
                .containsExactly("claimId", "status");
    }

    @Test
    @DisplayName("shape normalization: equivalent templates join, different shapes never collide")
    void pathShapes() {
        ConsumerDeclaration c = parser.parse(Fixtures.consumer("mobile-app.yaml"));
        // /claims/{claimId} → /claims/{0}; must NOT equal a hypothetical /other/{claimId}
        assertThat(c.forProvider("claims-api").get(1).pathShape()).isEqualTo("/claims/{0}");
        assertThat(PathShapeProbe.shapeOf("/quotes/{id}")).isEqualTo(PathShapeProbe.shapeOf("/quotes/{quoteId}"));
        assertThat(PathShapeProbe.shapeOf("/quotes/{id}"))
                .isNotEqualTo(PathShapeProbe.shapeOf("/x/quotes/{id}"));
    }

    @Test
    @DisplayName("collect-all errors: missing consumer name and bad method reported together")
    void collectsErrors() {
        String bad = """
                team: X
                uses:
                - provider: quote-api
                  method: FETCH
                  path: /quotes
                """;
        assertThatThrownBy(() -> parser.parse(bad, "bad.yaml"))
                .isInstanceOf(ConsumerParseException.class)
                .hasMessageContaining("bad.yaml")
                .hasMessageContaining("'consumer' is required")
                .hasMessageContaining("FETCH");
    }

    @Test
    @DisplayName("structural errors: non-list sends, non-mapping use entry, non-string fields")
    void structuralErrors() {
        assertThatThrownBy(() -> parser.parse("""
                consumer: c
                uses:
                - provider: p
                  method: GET
                  path: /x
                  sends: not-a-list
                """))
                .isInstanceOf(ConsumerParseException.class)
                .hasMessageContaining("sends must be a list");

        assertThatThrownBy(() -> parser.parse("""
                consumer: c
                uses: [just-a-string]
                """))
                .isInstanceOf(ConsumerParseException.class)
                .hasMessageContaining("uses[0] must be a mapping");

        assertThatThrownBy(() -> parser.parse("""
                consumer: c
                uses:
                - provider: p
                  method: GET
                  path: no-leading-slash
                """))
                .isInstanceOf(ConsumerParseException.class)
                .hasMessageContaining("must start with '/'");
    }

    @Test
    @DisplayName("empty usage list and missing sends/reads are valid (nothing declared)")
    void emptyDeclarations() {
        ConsumerDeclaration c = parser.parse("""
                consumer: silent-consumer
                uses: []
                """);
        assertThat(c.name()).isEqualTo("silent-consumer");
        assertThat(c.operations()).isEmpty();

        ConsumerDeclaration minimal = parser.parse("""
                consumer: minimal
                uses:
                - provider: svc
                  method: GET
                  path: /x
                """);
        assertThat(minimal.operations()).hasSize(1);
        assertThat(minimal.operations().get(0).sends()).isEmpty();
        assertThat(minimal.operations().get(0).reads()).isEmpty();
    }

    @Test
    @DisplayName("duplicate field declarations are de-duplicated preserving first-seen order")
    void dedupes() {
        ConsumerDeclaration c = parser.parse("""
                consumer: c
                uses:
                - provider: svc
                  method: GET
                  path: /x
                  reads: [a, b, a, b.c]
                """);
        assertThat(c.operations().get(0).reads()).containsExactly("a", "b", "b.c");
    }

    /** Visibility shim: PathShapes lives in the specs package; used here only for cross-checks. */
    private static final class PathShapeProbe {
        static String shapeOf(String path) {
            return com.contractguard.specs.PathShapes.normalize(path);
        }
    }
}

package com.contractguard.consumers;

import java.nio.file.Path;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.io.IOException;
import java.nio.file.Files;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/**
 * The registry loads ALL declaration files from a directory eagerly and
 * deterministically. Verified against the real (read-only) kit directory.
 */
class ConsumerRegistryTest {

    @Test
    @DisplayName("kit directory: all four consumers load, names preserved, deterministic order")
    void loadsKitDirectory() {
        ConsumerRegistry registry = new ConsumerRegistry(Path.of("consumers"));
        assertThat(registry.size()).isEqualTo(4);
        assertThat(registry.all()).extracting(ConsumerDeclaration::name)
                .containsExactly("mobile-app", "partner-portal", "payments-svc", "notifications-svc");
        assertThat(registry.byName("payments-svc")).isPresent();
        assertThat(registry.byName("nope")).isEmpty();
    }

    @Test
    @DisplayName("a broken declaration file fails startup loudly, naming the file")
    void brokenFileFailsLoudly(@TempDir Path dir) throws IOException {
        Files.writeString(dir.resolve("good.yaml"), """
                consumer: good
                uses: []
                """);
        Files.writeString(dir.resolve("broken.yaml"), """
                consumer: broken
                uses:
                - method: GET
                """);
        assertThatThrownBy(() -> new ConsumerRegistry(dir))
                .isInstanceOf(ConsumerParseException.class)
                .hasMessageContaining("broken.yaml")
                .hasMessageContaining("provider is required");
    }

    @Test
    @DisplayName("missing directory fails with a clear message")
    void missingDirectory() {
        assertThatThrownBy(() -> new ConsumerRegistry(Path.of("does-not-exist")))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("consumer directory not found");
    }
}

package com.contractguard.impact;

import java.util.List;
import java.util.Optional;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import com.contractguard.compatibility.CompatibilityEngine;
import com.contractguard.compatibility.CompatibilityFinding;
import com.contractguard.compatibility.Severity;
import com.contractguard.consumers.ConsumerDeclaration;
import com.contractguard.consumers.ConsumerParser;
import com.contractguard.consumers.DeclaredOperation;
import com.contractguard.specs.SpecDocument;
import com.contractguard.specs.SpecParser;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * Focused tier-classification tests over synthetic spec pairs. Everything runs through
 * the REAL SpecParser → CompatibilityEngine pipeline; the analyzer must never invent
 * usage and must explain every classification in its reason text.
 */
class ConsumerImpactAnalyzerTest {

    private final SpecParser specParser = new SpecParser();
    private final CompatibilityEngine engine = new CompatibilityEngine();
    private final ConsumerImpactAnalyzer analyzer = new ConsumerImpactAnalyzer();
    private final ConsumerParser consumerParser = new ConsumerParser();

    private static final String OLD = """
            openapi: 3.0.3
            info: {title: T, version: 1.0.0}
            paths:
              /quotes/{id}:
                get:
                  parameters: [{name: id, in: path, required: true, schema: {type: string}}]
                  responses:
                    '200':
                      description: ok
                      content:
                        application/json:
                          schema:
                            type: object
                            required: [quoteId, premium]
                            properties:
                              quoteId: {type: string}
                              status: {type: string}
                              premium:
                                type: object
                                properties:
                                  total: {type: number}
                                  currency: {type: string}
                                  breakdown:
                                    type: array
                                    items:
                                      type: object
                                      required: [label, amount]
                                      properties:
                                        label: {type: string}
                                        amount: {type: number}
            """;

    private ImpactSummary analyze(String service, String newYaml, String consumerYaml) {
        SpecDocument oldDoc = specParser.parse(OLD);
        SpecDocument newDoc = specParser.parse(newYaml);
        List<CompatibilityFinding> findings = engine.diff(oldDoc.getEffectiveSchemas(),
                newDoc.getEffectiveSchemas(), oldDoc.getPathAliases(), newDoc.getPathAliases());
        ConsumerDeclaration consumer = consumerParser.parse(consumerYaml);
        return analyzer.analyze(service, oldDoc, newDoc, findings, List.of(consumer));
    }

    private static ConsumerImpact single(ImpactSummary summary) {
        assertThat(summary.consumers()).hasSize(1);
        return summary.consumers().get(0);
    }

    // ------------------------------------------------------------- response side

    @Test
    @DisplayName("RESP.PROPERTY_REMOVED: exact reader AFFECTED, sibling reader NONE, non-reader's other operations untouched")
    void responseRemovalTiers() {
        String newY = OLD.replace("amount: {type: number}", "").replace("required: [label, amount]", "required: [label]");

        ImpactSummary reader = analyze("svc", newY, """
                consumer: c
                uses:
                - {provider: svc, method: GET, path: /quotes/{quoteId}, reads: [premium.breakdown[].amount]}
                """);
        assertThat(single(reader).level()).isEqualTo(ImpactLevel.AFFECTED);
        assertThat(single(reader).impacts().get(0).reason()).contains("premium.breakdown[].amount");

        ImpactSummary sibling = analyze("svc", newY, """
                consumer: c
                uses:
                - {provider: svc, method: GET, path: /quotes/{quoteId}, reads: [premium.breakdown[].label]}
                """);
        assertThat(single(sibling).level()).isEqualTo(ImpactLevel.NONE);
        assertThat(single(sibling).impacts().get(0).reason()).contains("do not include");

        // user of the operation with NO declared reads: dependence unknown → POSSIBLE
        ImpactSummary silent = analyze("svc", newY, """
                consumer: c
                uses:
                - {provider: svc, method: GET, path: /quotes/{quoteId}, sends: [id]}
                """);
        assertThat(single(silent).level()).isEqualTo(ImpactLevel.POSSIBLE);
        assertThat(single(silent).impacts().get(0).reason()).contains("cannot be ruled out");
    }

    @Test
    @DisplayName("ancestor matching: reader of 'premium.breakdown' is hit by an item-field change; 'premium.total' is not")
    void ancestorAndSiblingMatching() {
        String newY = OLD.replace("amount: {type: number}", "").replace("required: [label, amount]", "required: [label]");

        ImpactSummary arrayReader = analyze("svc", newY, """
                consumer: c
                uses:
                - {provider: svc, method: GET, path: /quotes/{quoteId}, reads: [premium.breakdown]}
                """);
        assertThat(single(arrayReader).level()).isEqualTo(ImpactLevel.AFFECTED);

        ImpactSummary objectReader = analyze("svc", newY, """
                consumer: c
                uses:
                - {provider: svc, method: GET, path: /quotes/{quoteId}, reads: [premium]}
                """);
        assertThat(single(objectReader).level()).isEqualTo(ImpactLevel.AFFECTED);
    }

    @Test
    @DisplayName("RESP.ENUM_WIDENED (advisory widening): declared reader lands in POSSIBLE, never AFFECTED")
    void wideningIsPossibleNotAffected() {
        String newY = OLD.replace("status: {type: string}", "status: {type: string, enum: [A, B]}");
        ImpactSummary reader = analyze("svc", newY, """
                consumer: c
                uses:
                - {provider: svc, method: GET, path: /quotes/{quoteId}, reads: [status]}
                """);
        assertThat(single(reader).level()).isEqualTo(ImpactLevel.POSSIBLE);
        assertThat(single(reader).impacts().get(0).findingCode()).isEqualTo("RESP.ENUM_WIDENED");
        assertThat(single(reader).impacts().get(0).reason()).contains("may return values");
    }

    // ------------------------------------------------------------- request side

    @Test
    @DisplayName("REQ.PROPERTY_REMOVED: sender of the field AFFECTED; sender of siblings NONE; empty sends POSSIBLE")
    void requestRemovalTiers() {
        String oldY = """
                openapi: 3.0.3
                info: {title: T, version: 1.0.0}
                paths:
                  /quotes:
                    post:
                      requestBody:
                        content:
                          application/json:
                            schema:
                              type: object
                              properties:
                                make: {type: string}
                                model: {type: string}
                      responses: {'200': {description: ok}}
                """;
        String newY = oldY.replace("model: {type: string}", "");

        ImpactSummary sender = analyze("svc", newY, """
                consumer: c
                uses:
                - {provider: svc, method: POST, path: /quotes, sends: [make, model]}
                """);
        assertThat(single(sender).level()).isEqualTo(ImpactLevel.AFFECTED);
        assertThat(single(sender).impacts().get(0).reason()).contains("you send 'model'");

        ImpactSummary siblingSender = analyze("svc", newY, """
                consumer: c
                uses:
                - {provider: svc, method: POST, path: /quotes, sends: [make]}
                """);
        assertThat(single(siblingSender).level()).isEqualTo(ImpactLevel.NONE);
        assertThat(single(siblingSender).impacts().get(0).reason()).contains("do not include");

        ImpactSummary silent = analyze("svc", newY, """
                consumer: c
                uses:
                - {provider: svc, method: POST, path: /quotes, reads: [x]}
                """);
        assertThat(single(silent).level()).isEqualTo(ImpactLevel.POSSIBLE);
    }

    @Test
    @DisplayName("REQ.REQUIRED_ADDED inverse logic: exact/subfield sender NONE, container sender POSSIBLE, proven non-sender AFFECTED")
    void requiredAddedInverse() {
        String oldY = """
                openapi: 3.0.3
                info: {title: T, version: 1.0.0}
                paths:
                  /endorsements:
                    post:
                      requestBody:
                        content:
                          application/json:
                            schema:
                              type: object
                              properties:
                                type: {type: string}
                                details: {type: string}
                      responses: {'200': {description: ok}}
                """;
        String newY = oldY.replace("properties:", "required: [requestedBy]\\n                              properties:")
                .replace("details: {type: string}", "details: {type: string}\\n                                requestedBy: {type: string}");

        ImpactSummary compliant = analyze("svc", newY, """
                consumer: c
                uses:
                - {provider: svc, method: POST, path: /endorsements, sends: [type, requestedBy]}
                """);
        assertThat(single(compliant).level()).isEqualTo(ImpactLevel.NONE);
        assertThat(single(compliant).impacts().get(0).reason()).contains("already declares sending");

        ImpactSummary container = analyze("svc", newY, """
                consumer: c
                uses:
                - {provider: svc, method: POST, path: /endorsements, sends: [requestedBy.name]}
                """);
        // sending a subfield implies sending the parent → compliant
        assertThat(single(container).level()).isEqualTo(ImpactLevel.NONE);

        ImpactSummary containerOnly = analyze("svc", newY, """
                consumer: c
                uses:
                - {provider: svc, method: POST, path: /endorsements, sends: [endorsement]}
                """);
        // 'endorsement' would be an ancestor of 'requestedBy' only if the field were nested;
        // here it is a sibling name → proven non-sender → AFFECTED
        assertThat(single(containerOnly).level()).isEqualTo(ImpactLevel.AFFECTED);
        assertThat(single(containerOnly).impacts().get(0).reason()).contains("now required");

        ImpactSummary nonSender = analyze("svc", newY, """
                consumer: c
                uses:
                - {provider: svc, method: POST, path: /endorsements, sends: [type, details]}
                """);
        assertThat(single(nonSender).level()).isEqualTo(ImpactLevel.AFFECTED);

        ImpactSummary emptySends = analyze("svc", newY, """
                consumer: c
                uses:
                - {provider: svc, method: POST, path: /endorsements}
                """);
        // nothing declared → not provably compliant → AFFECTED (conservative, per policy)
        assertThat(single(emptySends).level()).isEqualTo(ImpactLevel.AFFECTED);
    }

    @Test
    @DisplayName("rename: readers of the old path AND of the derived new path are AFFECTED; sibling reader NONE")
    void renameMatching() {
        String newY = OLD.replace("amount: {type: number}", "value: {type: number}")
                .replace("required: [label, amount]", "required: [label, value]");

        ImpactSummary oldReader = analyze("svc", newY, """
                consumer: c
                uses:
                - {provider: svc, method: GET, path: /quotes/{quoteId}, reads: [premium.breakdown[].amount]}
                """);
        assertThat(single(oldReader).level()).isEqualTo(ImpactLevel.AFFECTED);
        assertThat(single(oldReader).impacts().get(0).reason()).contains("renamed to 'value'");

        ImpactSummary newReader = analyze("svc", newY, """
                consumer: c
                uses:
                - {provider: svc, method: GET, path: /quotes/{quoteId}, reads: [premium.breakdown[].value]}
                """);
        assertThat(single(newReader).level()).isEqualTo(ImpactLevel.AFFECTED);

        ImpactSummary sibling = analyze("svc", newY, """
                consumer: c
                uses:
                - {provider: svc, method: GET, path: /quotes/{quoteId}, reads: [premium.breakdown[].label]}
                """);
        assertThat(single(sibling).level()).isEqualTo(ImpactLevel.NONE);
    }

    // ------------------------------------------------------------- parameters & operations

    @Test
    @DisplayName("PARAM.REQUIRED_ADDED: binder not sending the param AFFECTED; pre-adapted binder NONE; non-binders untouched")
    void parameterImpact() {
        String oldY = """
                openapi: 3.0.3
                info: {title: T, version: 1.0.0}
                paths:
                  /cache:
                    delete:
                      responses: {'204': {description: cleared}}
                """;
        String newY = oldY.replace("responses:", "parameters: [{name: region, in: query, required: true, schema: {type: string}}]\\n                      responses:");

        ImpactSummary binder = analyze("svc", newY, """
                consumer: c
                uses:
                - {provider: svc, method: DELETE, path: /cache}
                """);
        assertThat(single(binder).level()).isEqualTo(ImpactLevel.AFFECTED);
        assertThat(single(binder).impacts().get(0).findingCode()).isEqualTo("PARAM.REQUIRED_ADDED");
        assertThat(single(binder).impacts().get(0).reason()).contains("'region'");

        ImpactSummary preAdapted = analyze("svc", newY, """
                consumer: c
                uses:
                - {provider: svc, method: DELETE, path: /cache, sends: [region]}
                """);
        assertThat(single(preAdapted).level()).isEqualTo(ImpactLevel.NONE);
        assertThat(single(preAdapted).impacts().get(0).reason()).contains("already declares sending");
    }

    @Test
    @DisplayName("PARAM name resolution: consumer 'sends: [region]' matches even though envelopes drop names")
    void parameterNameResolvedThroughSpecsModule() {
        // param becomes required (existed before): name resolved from BOTH docs
        String oldY = """
                openapi: 3.0.3
                info: {title: T, version: 1.0.0}
                paths:
                  /cache:
                    delete:
                      parameters: [{name: region, in: query, required: false, schema: {type: string}}]
                      responses: {'204': {description: cleared}}
                """;
        String newY = oldY.replace("required: false", "required: true");

        ImpactSummary nonSender = analyze("svc", newY, """
                consumer: c
                uses:
                - {provider: svc, method: DELETE, path: /cache, sends: []}
                """);
        assertThat(single(nonSender).level()).isEqualTo(ImpactLevel.AFFECTED);

        ImpactSummary sender = analyze("svc", newY, """
                consumer: c
                uses:
                - {provider: svc, method: DELETE, path: /cache, sends: [region]}
                """);
        assertThat(single(sender).level()).isEqualTo(ImpactLevel.NONE);
    }

    @Test
