    }

    @Test
    @DisplayName("REQ.REQUIRED_ADDED inverse logic: exact/subfield sender NONE, proven non-sender AFFECTED, empty sends AFFECTED")
    void requiredAddedInverse() {
        String oldY = """
                openapi: 3.0.3
                info: {title: T, version: 1.0.0}
                paths:
                  /endorsements:
                    post:
                      requestBody:
                        content:
                          application/json:
                            schema:
                              type: object
                              properties:
                                type: {type: string}
                                details: {type: string}
                      responses: {'200': {description: ok}}
                """;
        String newY = """
                openapi: 3.0.3
                info: {title: T, version: 1.0.0}
                paths:
                  /endorsements:
                    post:
                      requestBody:
                        content:
                          application/json:
                            schema:
                              type: object
                              required: [requestedBy]
                              properties:
                                type: {type: string}
                                details: {type: string}
                                requestedBy: {type: string}
                      responses: {'200': {description: ok}}
                """;

        ImpactSummary compliant = analyze("svc", newY, """
                consumer: c
                uses:
                - provider: svc
                  method: POST
                  path: /endorsements
                  sends: [type, requestedBy]
                """);
        assertThat(single(compliant).level()).isEqualTo(ImpactLevel.NONE);
        assertThat(single(compliant).impacts().get(0).reason()).contains("already declares sending");

        // sending a subfield (requestedBy.name) implies the parent object is sent → compliant
        ImpactSummary subfieldSender = analyze("svc", newY, """
                consumer: c
                uses:
                - provider: svc
                  method: POST
                  path: /endorsements
                  sends: [requestedBy.name]
                """);
        assertThat(single(subfieldSender).level()).isEqualTo(ImpactLevel.NONE);

        // sibling-name sender: proven NOT to send the now-required field → AFFECTED
        ImpactSummary nonSender = analyze("svc", newY, """
                consumer: c
                uses:
                - provider: svc
                  method: POST
                  path: /endorsements
                  sends: [type, details]
                """);
        assertThat(single(nonSender).level()).isEqualTo(ImpactLevel.AFFECTED);
        assertThat(single(nonSender).impacts().get(0).reason()).contains("now required");

        // nothing declared on the request side → not provably compliant → AFFECTED
        ImpactSummary emptySends = analyze("svc", newY, """
                consumer: c
                uses:
                - provider: svc
                  method: POST
                  path: /endorsements
                """);
        assertThat(single(emptySends).level()).isEqualTo(ImpactLevel.AFFECTED);
    }

