/** TEMPORARY diagnostic — prints engine output for the failing synthetic pairs. */
class ScratchDiagnosticTest {

    @Test
    void dump() {
        String oldY = """
                openapi: 3.0.3
                info: {title: T, version: 1.0.0}
                paths:
                  /quotes:
                    post:
                      requestBody:
                        content:
                          application/json:
                            schema:
