                openapi: 3.0.3
                info: {title: T, version: 1.0.0}
                paths:
                  /quotes:
                    post:
                      requestBody:
                        content:
                          application/json:
                            schema: {type: object, required: [cc], properties: {make: {type: string}, cc: {type: integer}}}
                      responses: {'200': {description: ok}}
                  /other:
                    get:
                      responses: {'200': {description: ok}}
                """;
        SpecParser parser = new SpecParser();
        SpecDocument o = parser.parse(oldY);
        SpecDocument n = parser.parse(newY);
        List<CompatibilityFinding> findings = new CompatibilityEngine().diff(
                o.getEffectiveSchemas(), n.getEffectiveSchemas(), o.getPathAliases(), n.getPathAliases());
        System.out.println("OLD EFFECTIVE:");
        o.getEffectiveSchemas().forEach((k, v) -> System.out.println("  " + k + " => " + v));
        System.out.println("NEW EFFECTIVE:");
        n.getEffectiveSchemas().forEach((k, v) -> System.out.println("  " + k + " => " + v));
        System.out.println("FINDINGS: " + findings.size());
        findings.forEach(f -> System.out.println("  " + f.code() + " " + f.severity() + " loc=" + f.location()
                + " field=" + f.fieldPath() + " detail=" + f.detail()));
    }
}

