5: /**
6:  * Minimal semver value object for the version-policy channel. Accepts "X.Y.Z" and
7:  * "X.Y" (patch defaults to 0), optional leading "v", optional "-suffix" ignored.
8:  * Never used to decide compatibility — only to AUDIT whether the bump type matches
9:  * the actual change profile (PLAN.md policy rule 5).
10:  */
11: public record Semver(long major, long minor, long patch) implements Comparable<Semver> {
12: 
13:     public static Optional<Semver> parse(String raw) {
14:         if (raw == null) {
15:             return Optional.empty();
16:         }
17:         String cleaned = raw.trim();
18:         if (cleaned.startsWith("v") || cleaned.startsWith("V")) {
19:             cleaned = cleaned.substring(1);
20:         }
21:         int suffix = cleaned.indexOf('-');
22:         if (suffix >= 0) {
23:             cleaned = cleaned.substring(0, suffix);
24:         }
25:         String[] parts = cleaned.split("\\.");
26:         if (parts.length < 2 || parts.length > 3) {
27:             return Optional.empty();
28:         }
29:         try {
30:             long major = Long.parseLong(parts[0]);
31:             long minor = Long.parseLong(parts[1]);
32:             long patch = parts.length == 3 ? Long.parseLong(parts[2]) : 0L;
33:             if (major < 0 || minor < 0 || patch < 0) {
34:                 return Optional.empty();
35:             }
36:             return Optional.of(new Semver(major, minor, patch));
37:         } catch (NumberFormatException e) {
38:             return Optional.empty();
39:         }
40:     }
41: 
42:     public enum Bump { NONE, PATCH, MINOR, MAJOR }
43: 
44:     public static Bump bump(Semver oldVersion, Semver newVersion) {
45:         if (newVersion.major != oldVersion.major) {
46:             return Bump.MAJOR;
47:         }
48:         if (newVersion.minor != oldVersion.minor) {
49:             return Bump.MINOR;
50:         }
51:         if (newVersion.patch != oldVersion.patch) {
52:             return Bump.PATCH;
53:         }
54:         return Bump.NONE;
55:     }
56: 
57:     @Override
58:     public int compareTo(Semver other) {
59:         int byMajor = Long.compare(major, other.major);
60:         if (byMajor != 0) {
61:             return byMajor;
62:         }
63:         int byMinor = Long.compare(minor, other.minor);
64:         if (byMinor != 0) {
65:             return byMinor;
66:         }
67:         return Long.compare(patch, other.patch);
68:     }
