371:     private TypeRelation compareType(LocationKeys.Operation op, String path, String locationKey,
372:                                      SchemaSide side, JsonNode oldNode, JsonNode newNode,
373:                                      String fieldPath, List<CompatibilityFinding> out) {
374:         Set<String> oldTypes = typeSet(oldNode);
375:         Set<String> newTypes = typeSet(newNode);
376:         if (oldTypes.equals(newTypes)) {
377:             return TypeRelation.EQUAL;
378:         }
379:         TypeRelation relation;
380:         if (oldTypes.isEmpty() || newTypes.isEmpty()) {
381:             relation = oldTypes.isEmpty() ? TypeRelation.NARROWED : TypeRelation.WIDENED;
382:         } else if (oldTypes.containsAll(newTypes)) {
383:             relation = TypeRelation.NARROWED;
384:         } else if (newTypes.containsAll(oldTypes)) {
385:             relation = TypeRelation.WIDENED;
386:         } else {
387:             relation = TypeRelation.DISJOINT;
388:         }
389:         switch (relation) {
390:             case NARROWED -> emit(op, path, locationKey, side, fieldPath,
391:                     "REQ.TYPE_NARROWED", Severity.BREAKING, "RESP.TYPE_NARROWED", Severity.INFO,
392:                     "accepted type(s) narrowed from " + oldTypes + " to " + newTypes,
393:                     JsonWriter.write(oldNode.get("type")), JsonWriter.write(newNode.get("type")), out);
394:             case WIDENED -> emit(op, path, locationKey, side, fieldPath,
395:                     "REQ.TYPE_WIDENED", Severity.INFO, "RESP.TYPE_WIDENED", Severity.BREAKING,
396:                     "accepted type(s) widened from " + oldTypes + " to " + newTypes,
397:                     JsonWriter.write(oldNode.get("type")), JsonWriter.write(newNode.get("type")), out);
398:             case DISJOINT -> emit(op, path, locationKey, side, fieldPath,
399:                     "REQ.TYPE_NARROWED", Severity.BREAKING, "RESP.TYPE_CHANGED", Severity.BREAKING,
400:                     "type changed from " + oldTypes + " to " + newTypes,
401:                     JsonWriter.write(oldNode.get("type")), JsonWriter.write(newNode.get("type")), out);
402:             default -> { /* EQUAL: nothing */ }
403:         }
404:         return relation;
