public Map<String,Object> upload(String slug, String yaml, String filename, String actor, boolean notify) {
  ServiceRow service = store.findService(slug).orElseThrow(() -> new NotFoundException("service not found: " + slug));
  String sha = sha256(yaml);
  SpecDocument doc;
  try {
    doc = specParser.parse(yaml);
  } catch (SpecParseException e) {
    String versionLabel = "(unknown)";
    long attemptId = store.insertRejectedAttempt(service.id(), versionLabel, sha, yaml, errorText(e.getErrors()), actor, "SPEC_REJECTED");
    store.insertAuditEvent(slug, versionLabel, attemptId, "SPEC_REJECTED", "rejected", actor, "invalid specification: " + errorText);
    throw new SpecInvalidException(e.getErrors(), attemptId);
  }
  String version = doc.getSpecVersion();
  Optional<SpecVersionRow> existing = store.findVersion(service.id(), version);
  if (existing.isPresent()) {
    if (existing.get().canonicalJson().equals(doc.getCanonicalJson())) {
      store.insertAuditEvent(slug, version, null, "SPEC_DUPLICATE_IDENTICAL", "no-op", actor, "identical re-upload of stored version " + version);
      return Map.of("status", "duplicate-identical", "service", slug, "version", version, "message", "this exact version is already registered (idempotent no-op)");
    }
    long attemptId = store.insertRejectedAttempt(service.id(), version, sha, yaml, "version " + version + " already registered with different content", actor, "SPEC_REJECTED");
    store.insertAuditEvent(slug, version, attemptId, "SPEC_REJECTED", "rejected", actor, "duplicate version with different content");
    throw new ConflictException("version " + version + " is already registered with different content; rejections never reserve a version");
  }
  // regression
  Optional<SpecVersionRow> current = store.currentVersion(service.id());
  if (current.isPresent()) {
    Optional<Semver> oldV = Semver.parse(current.get().version());
    Optional<Semver> newV = Semver.parse(version);
    if (oldV.isPresent() && newV.isPresent() && newV.get().compareTo(oldV.get()) < 0) {
      attempt rejected + audit; throw new ConflictException("version regression: " + version + " is lower than the current published version " + current.get().version());
    }
  }
  Evaluation evaluation = evaluate(slug, current.orElse(null), doc);
  return gate(service, doc, evaluation, sha, filename, actor, notify);
}
```

