285:             ps.setString(2, incomingVersion);
286:             ps.setString(3, sourceSha);
287:             ps.setString(4, rawYaml);
288:             ps.setString(5, note);
289:             return ps;
290:         }, keys);
291:         long attemptId = keys.getKey() == null ? -1 : keys.getKey().longValue();
292:         jdbc.update("INSERT INTO attempt_transitions (attempt_id, from_state, to_state, actor) "
293:                 + "VALUES (?, 'received', 'rejected', ?)", attemptId, actor);
294:         jdbc.update("""
295:                         INSERT INTO audit_events (service, version, attempt_id, action, decision, actor, justification, details)
296:                         VALUES ((SELECT slug FROM services WHERE id = ?), ?, ?, ?, ?, ?, ?, ?)
297:                         """, serviceId, incomingVersion, attemptId, audit.action(), audit.decision(),
298:                 actor, audit.justification(), audit.details());
299:         return attemptId;
300:     }
301: 
302:     /**
303:      * Rule-1 auto-publication: gated attempt (no breaking findings) + published spec
304:      * version row in ONE transaction, so "published" is never visible without its
305:      * findings/audit trail and vice versa.
306:      */
307:     @Transactional
308:     public long autoPublishAttempt(long serviceId, String incomingVersion, String sourceSha,
309:                                    String sourceFilename, String rawYaml, String canonicalJson,
310:                                    String effectiveJson, String publishedBy, String decisionJson,
311:                                    List<FindingWithImpacts> findings, String actor, AuditEntry audit) {
312:         long attemptId = insertGatedAttempt(serviceId, incomingVersion, sourceSha, rawYaml,
313:                 canonicalJson, "auto_published", 0, "none: publication permitted", decisionJson,
314:                 findings, actor, audit);
315:         publishVersion(serviceId, incomingVersion, sourceSha, sourceFilename, rawYaml,
316:                 canonicalJson, effectiveJson, publishedBy);
317:         return attemptId;
318:     }
319: 
320:     /**
321:      * Completes a human decision: appends the guarded transition, updates the attempt
322:      * state, writes the audit row and (for publish outcomes) stores the spec version —
323:      * atomically. The transition row is written BEFORE the state update so its
324:      * {@code from_state} is the genuine previous state.
325:      */
326:     @Transactional
327:     public void decideAndPublish(long attemptId, long serviceId, String slug, String version,
328:                                  String previousState, String sourceSha, String sourceFilename,
329:                                  String rawYaml, String canonicalJson, String effectiveJson,
330:                                  String newState, String actor, String justification,
331:                                  String auditAction, String auditDetails) {
332:         jdbc.update("INSERT INTO attempt_transitions (attempt_id, from_state, to_state, actor, comment) "
333:                         + "VALUES (?, ?, ?, ?, ?)",
334:                 attemptId, previousState, newState, actor, justification);
335:         jdbc.update("UPDATE publication_attempts SET state = ?, decided_at = CURRENT_TIMESTAMP, "
336:                 + "decided_by = ?, justification = COALESCE(?, justification) WHERE id = ?",
337:                 newState, actor, justification, attemptId);
338:         jdbc.update("INSERT INTO audit_events (service, version, attempt_id, action, decision, actor, justification, details) "
339:                 + "VALUES (?, ?, ?, ?, ?, ?, ?, ?)", slug, version, attemptId, auditAction, newState,
340:                 actor, justification, auditDetails);
341:         if (canonicalJson != null) {
342:             jdbc.update("UPDATE spec_versions SET state = 'superseded' "
343:                     + "WHERE service_id = ? AND state = 'published'", serviceId);
344:             jdbc.update("""
345:                             INSERT INTO spec_versions (service_id, version, source_sha, source_filename,
346:                                 raw_yaml, canonical_json, effective_json, state, published_by)
347:                             VALUES (?, ?, ?, ?, ?, ?, ?, 'published', ?)
348:                             """,
349:                     serviceId, version, sourceSha, sourceFilename, rawYaml, canonicalJson,
350:                     effectiveJson, actor);
351:         }
352:     }
