354:     private void insertFindings(long attemptId, List<FindingWithImpacts> findings) {
355:         for (FindingWithImpacts finding : findings) {
356:             KeyHolder keys = new GeneratedKeyHolder();
357:             jdbc.update(con -> {
358:                 var ps = con.prepareStatement("""
359:                                 INSERT INTO findings (attempt_id, code, severity, scope, method, path,
360:                                     location, field_path, detail, old_json, new_json)
361:                                 VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
362:                                 """,
363:                         new String[]{"id"});
364:                 ps.setLong(1, attemptId);
365:                 ps.setString(2, finding.code());
366:                 ps.setString(3, finding.severity());
367:                 ps.setString(4, finding.scope());
368:                 ps.setString(5, finding.method());
369:                 ps.setString(6, finding.path());
370:                 ps.setString(7, finding.location());
371:                 ps.setString(8, finding.fieldPath());
372:                 ps.setString(9, finding.detail());
373:                 ps.setString(10, finding.oldJson());
374:                 ps.setString(11, finding.newJson());
375:                 return ps;
376:             }, keys);
377:             long findingId = keys.getKey() == null ? -1 : keys.getKey().longValue();
378:             for (FindingWithImpacts.ImpactEntry impact : finding.impacts()) {
379:                 jdbc.update("INSERT INTO finding_impacts (finding_id, consumer, level, evidence_json) "
380:                         + "VALUES (?, ?, ?, ?)", findingId, impact.consumer(), impact.level(),
381:                         impact.reason());
382:             }
383:         }
384:     }
