340:     /**
341:      * Deprecation lifecycle findings (PLAN.md §6): a newly {@code deprecated} field is a
342:      * warn (non-gating); an {@code x-sunset} date in the past/future while the field is
343:      * still documented is a warn/info. These never gate (severity never BREAKING).
344:      */
345:     private List<CompatibilityFinding> appendLifecycleFindings(List<CompatibilityFinding> findings,
346:                                                                SpecDocument oldDoc, SpecDocument newDoc) {
347:         Set<String> previouslyDeprecated = new TreeSet<>();
348:         for (DeprecationRecord record : oldDoc.getDeprecations()) {
349:             previouslyDeprecated.add(record.humanPath());
350:         }
351:         LocalDate today = LocalDate.now();
352:         for (DeprecationRecord record : newDoc.getDeprecations()) {
353:             String where = record.humanPath();
354:             if (!previouslyDeprecated.contains(where)) {
355:                 findings.add(new CompatibilityFinding("DEPRECATION.ADDED", Severity.WARN, "LIFECYCLE",
356:                         null, null, where, where,
357:                         "field newly marked deprecated"
358:                                 + record.sunsetRaw().map(s -> " (x-sunset: " + s + ")").orElse(""),
359:                         null, null));
360:             }
361:             record.sunset().ifPresent(date -> {
362:                 String code = date.isAfter(today) ? "SUNSET_SCHEDULED" : "SUNSET_PASSED";
363:                 Severity severity = date.isAfter(today) ? Severity.INFO : Severity.WARN;
364:                 String detail = "x-sunset date " + date + (date.isAfter(today)
365:                         ? " is scheduled"
366:                         : " has passed while the field is still documented");
367:                 findings.add(new CompatibilityFinding(code, severity, "LIFECYCLE", null, null,
368:                         where, where, detail, null, null));
369:             });
370:         }
371:         return findings;
372:     }
