261:     // ------------------------------------------------------------------ path helpers
262: 
263:     /**
264:      * First declared path overlapping the finding's old or new path: overlap means one
265:      * segment list is a prefix of the other ({@code []} markers are equated with their
266:      * parent segment, so an array and its items belong to one lineage). Returns the
267:      * DECLARED path for use in the reason text, or null.
268:      */
269:     private static String firstOverlap(List<String> declared, String oldPath, String newPath) {
270:         for (String candidate : declared) {
271:             if (overlaps(candidate, oldPath) || (newPath != null && overlaps(candidate, newPath))) {
272:                 return candidate;
273:             }
274:         }
275:         return null;
276:     }
277: 
278:     private static boolean overlaps(String a, String b) {
279:         return isPrefixOrEqual(segments(a), segments(b)) || isPrefixOrEqual(segments(b), segments(a));
280:     }
281: 
282:     private static boolean isPrefixOrEqual(List<String> prefix, List<String> longer) {
283:         if (prefix.size() > longer.size()) {
284:             return false;
285:         }
286:         for (int i = 0; i < prefix.size(); i++) {
287:             if (!prefix.get(i).equals(longer.get(i))) {
288:                 return false;
289:             }
290:         }
291:         return true;
292:     }
