294:     /** "premium.breakdown[].amount" → ["premium", "breakdown", "amount"] ([] markers equated). */
295:     private static List<String> segments(String fieldPath) {
296:         String[] parts = fieldPath.split("\\.");
297:         List<String> out = new ArrayList<>(parts.length);
298:         for (String part : parts) {
299:             out.add(part.endsWith("[]") ? part.substring(0, part.length() - 2) : part);
300:         }
301:         return out;
302:     }
