304:     /** For PROPERTY_RENAMED findings: fieldPath with its last segment replaced by the new name. */
305:     private static String renameNewPath(CompatibilityFinding f) {
306:         if (f.fieldPath() == null || !f.code().endsWith("PROPERTY_RENAMED")) {
307:             return null;
308:         }
309:         Matcher m = RENAME_IN_DETAIL.matcher(f.detail() == null ? "" : f.detail());
310:         if (!m.find()) {
311:             return null;
312:         }
313:         int lastDot = f.fieldPath().lastIndexOf('.');
314:         return lastDot < 0 ? m.group(2) : f.fieldPath().substring(0, lastDot + 1) + m.group(2);
315:     }
