317:     /** Short per-code verb phrase for reason texts. */
318:     private static String codePhrase(String code, String field, String newPath) {
319:         return switch (code) {
320:             case "RESP.PROPERTY_REMOVED" -> "was removed from responses";
321:             case "REQ.PROPERTY_REMOVED" -> "was removed from the accepted requests";
322:             case "RESP.REQUIRED_REMOVED" -> "is no longer guaranteed in responses";
323:             case "REQ.REQUIRED_REMOVED" -> "is no longer required in requests";
324:             case "RESP.PROPERTY_RENAMED", "REQ.PROPERTY_RENAMED" ->
325:                     "is renamed to '" + (newPath != null
326:                             ? newPath.substring(newPath.lastIndexOf('.') + 1) : "?") + "'";
327:             case "REQ.ENUM_NARROWED" -> "had accepted enum value(s) removed";
328:             case "REQ.TYPE_NARROWED", "REQ.CONSTRAINT_TIGHTENED" -> "was tightened";
329:             case "RESP.TYPE_CHANGED" -> "changed type";
330:             default -> "changed (" + code + ")";
331:         };
332:     }
