package com.contractguard.pipeline;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import com.contractguard.persistence.RegistryStore;

/**
 * Migration-guide generation from ACTUAL stored compatibility findings (no fabrication):
 * every step quotes a persisted finding's location/field and maps the finding code to a
 * concrete, grounded action for the teams that call the changed operation. Consumer
 * names come from the stored impact rows, so each step says WHO has to act.
 *
 * <p>Codes without a specific template fall back to a review step quoting the finding's
 * own detail text — a step is never invented beyond what the finding states. Parameter
 * names (deliberately absent from finding envelopes) are restored from the spec's
 * parameter-name index when available.
 */
public final class MigrationGuide {

    /** One grounded migration step. */
    public record Step(String code, String severity, String location, String fieldPath,
                       String action, List<String> consumers) {

        public Map<String, Object> view() {
            Map<String, Object> out = new LinkedHashMap<>();
            out.put("code", code);
            out.put("severity", severity);
            out.put("location", location == null ? "" : location);
            out.put("fieldPath", fieldPath == null ? "" : fieldPath);
            out.put("action", action);
            out.put("consumers", consumers);
            return out;
        }
    }

    private MigrationGuide() {
    }

    /**
     * @param findings         persisted findings of one attempt, in stored order
     * @param impactsByFinding stored impact rows keyed by finding id
     * @param paramNames       location → parameter-name index of the attempt's spec
     *                         (may be empty; used only to name parameters in actions)
     */
    public static List<Step> build(List<RegistryStore.StoredFinding> findings,
                                   Map<Long, List<RegistryStore.StoredImpact>> impactsByFinding,
                                   Map<String, String> paramNames) {
        List<Step> steps = new ArrayList<>();
        for (RegistryStore.StoredFinding finding : findings) {
            String field = finding.fieldPath();
            String where = finding.location() == null ? "" : finding.location();
            String param = paramName(finding, paramNames);
            String action = switch (finding.code()) {
                case "RESP.PROPERTY_RENAMED" -> action(field, "renamed" , finding.detail(),
                        "Update readers: the response field '" + field
                                + "' was renamed (see detail) — read the new name and remove"
                                + " uses of the old one.");
                case "RESP.PROPERTY_REMOVED" -> action(field, "removed from responses",
                        "Stop reading '" + field + "'; it is no longer part of responses."
                                + " Handle its absence explicitly.");
                case "RESP.REQUIRED_REMOVED" -> action(field, "no longer guaranteed",
                        "Do not rely on '" + field + "' always being present in responses;"
                                + " it is no longer a guaranteed field.");
                case "RESP.ENUM_WIDENED", "RESP.TYPE_WIDENED", "RESP.CONSTRAINT_LOOSENED",
                     "RESP.NULLABLE_ADDED" -> action(field, "response space widened",
                        "Extend handling in readers of '" + field + "' to cover the widened"
                                + " response space (new values/shapes): " + finding.detail());
                case "RESP.RESPONSE_REMOVED", "RESP.MEDIA_TYPE_REMOVED" ->
                        generic(finding, "Stop expecting this response/media type: "
                                + finding.detail());
                case "REQ.REQUIRED_ADDED" -> action(field, "now required in requests",
                        "Always send '" + field + "' on requests to this operation;"
                                + " requests without it will be rejected.");
                case "REQ.PROPERTY_REMOVED" -> action(field, "removed from requests",
                        "Stop sending '" + field + "'; the server no longer accepts it.");
                case "REQ.ENUM_NARROWED" -> action(field, "accepted values narrowed",
                        "Stop sending value(s) that are no longer accepted for '" + field
                                + "' (" + finding.detail() + ").");
                case "REQ.TYPE_NARROWED", "REQ.CONSTRAINT_TIGHTENED" -> action(field,
                        "request contract tightened",
                        "Conform sent values of '" + field + "' to the tightened contract: "
                                + finding.detail());
                case "PARAM.REQUIRED_ADDED" -> action(field, "parameter now required",
                        param != null
                                ? "Always send the '" + param + "' parameter on this operation;"
                                  + " requests without it will be rejected."
                                : "Send the newly required parameter on this operation"
                                  + " (see finding detail).");
                case "PARAM.REMOVED" -> action(field, "parameter removed",
                        param != null
                                ? "Stop sending the '" + param + "' parameter; it was removed."
                                : "Stop sending the removed parameter (see finding detail).");
                case "PATH_SHAPE.CHANGED" -> generic(finding,
                        "Update client routing/templating: the path shape of this operation"
                                + " changed (" + finding.detail() + ").");
                case "OPERATION.REMOVED", "PATH.REMOVED" -> generic(finding,
                        "Migrate callers off this operation; it no longer exists.");
                case "REQUEST_BODY.MADE_REQUIRED" -> generic(finding,
                        "Requests to this operation must now include a body.");
                case "DEPRECATION.ADDED" -> action(field, "newly deprecated",
                        "Plan migration off '" + field + "' before its sunset date ("
                                + finding.detail() + "); it will be removed.");
                case "SUNSET_PASSED" -> action(field, "past its sunset date",
                        "Remove remaining uses of '" + field + "' — its documented sunset date"
                                + " has passed while the field is still present.");
                case "SUNSET_SCHEDULED" -> action(field, "sunset scheduled",
                        "Track the planned removal of '" + field + "' (" + finding.detail()
                                + ") and prepare consumers.");
                case "CONSUMER.DRIFT" -> action(field, "consumer declaration drift",
                        "Update the consumer declarations named below: the declared usage no"
                                + " longer matches the incoming spec (" + finding.detail() + ").");
                case "CONSUMER.STALE_BINDING" -> generic(finding,
                        "Update the consumer declarations named below: the declared operation"
                                + " no longer exists in the incoming spec.");
                default -> generic(finding, "Review this change: " + finding.detail());
            };
            steps.add(new Step(finding.code(), finding.severity(), where, field, action,
                    consumersOf(finding, impactsByFinding)));
        }
        return steps;
    }

    private static String action(String field, String label, String action) {
        return field == null || field.isBlank()
                ? action
                : action + " (field: '" + field + "' — " + label + ")";
    }

    private static String action(String field, String label, String detailPrefix, String action) {
        String suffix = field == null || field.isBlank() ? "" : " (field: '" + field + "' — " + label + ")";
        return detailPrefix + suffix;
    }

    private static String generic(RegistryStore.StoredFinding finding, String action) {
        String suffix = finding.fieldPath() == null || finding.fieldPath().isBlank()
                ? "" : " (field: '" + finding.fieldPath() + "')";
        return action + suffix;
    }

    /** Parameter name restored from the spec's name index (finding envelopes omit it). */
    private static String paramName(RegistryStore.StoredFinding finding, Map<String, String> paramNames) {
        if (paramNames.isEmpty() || finding.location() == null
                || !finding.location().contains(" :: param:")) {
            return null;
        }
        return paramNames.get(finding.location());
    }

    private static List<String> consumersOf(RegistryStore.StoredFinding finding,
                                            Map<Long, List<RegistryStore.StoredImpact>> impactsByFinding) {
        List<String> out = new ArrayList<>();
        for (RegistryStore.StoredImpact impact : impactsByFinding.getOrDefault(finding.id(), List.of())) {
            String entry = impact.consumer() + " (" + impact.level().toUpperCase() + ")";
            if (!out.contains(entry)) {
                out.add(entry);
            }
        }
        return out;
    }
}

