22:     /** Canonicalizes a node into JSON-serializable Maps/Lists (sorted keys). */
23:     static Object canonicalize(JsonNode node) {
24:         if (node == null || node.isNull() || node.isMissingNode()) {
25:             return null;
26:         }
27:         if (node.isObject()) {
28:             Map<String, Object> sorted = new TreeMap<>();
29:             for (Map.Entry<String, JsonNode> entry : node.properties()) {
30:                 String key = entry.getKey();
31:                 JsonNode value = entry.getValue();
32:                 if ("required".equals(key) && value.isArray()) {
33:                     sorted.put(key, sortedTextList(value));
34:                 } else {
35:                     sorted.put(key, canonicalize(value));
36:                 }
37:             }
38:             return sorted;
39:         }
40:         if (node.isArray()) {
41:             List<Object> list = new ArrayList<>();
42:             for (JsonNode element : node) {
43:                 list.add(canonicalize(element));
44:             }
45:             return list;
46:         }
47:         if (node.isString()) {
48:             return node.stringValue();
49:         }
50:         if (node.isBoolean()) {
51:             return node.booleanValue();
52:         }
53:         if (node.isNumber()) {
54:             return node.numberValue();
55:         }
56:         // null, POJO, binary etc.: fall back to the node itself; Jackson serializes it as-is
57:         return node;
58:     }
