package com.contractguard.impact;

import org.junit.jupiter.api.Test;
import com.contractguard.specs.Fixtures;
import com.contractguard.specs.SpecParser;
import tools.jackson.databind.json.JsonMapper;

import java.util.Map;

class ScratchPrintSchemasTest {
    @Test
    void print() throws Exception {
        SpecParser p = new SpecParser();
        var doc = p.parse(Fixtures.spec("quote-api", "1-initial.yaml"));
        JsonMapper mapper = JsonMapper.builder().build();
        for (Map.Entry<String, String> e : doc.getEffectiveSchemas().entrySet()) {
            if (!e.getKey().contains("response:200")) continue;
            String json = e.getValue();
            System.out.println("JSONLEN>> " + (json == null ? "null" : json.length()));
            try {
                var node = mapper.readTree(json);
                System.out.println("READTREE OK class=" + node.getClass().getName()
                        + " isObject=" + node.isObject()
                        + " hasQuoteId=" + (node.get("properties") == null ? "no-props"
                                : node.get("properties").get("quoteId") != null));
            } catch (Throwable t) {
                System.out.println("READTREE THREW>> " + t.getClass().getName() + ": " + t.getMessage());
                t.printStackTrace(System.out);
            }
        }
    }
}

