document.getElementById('migrationGuideBtn').addEventListener('click', async () => {
  const id = document.getElementById('attemptId').value.trim();
  if (!id) {
    document.getElementById('migrationOut').innerHTML =
      '<p class="muted">Enter an attempt id first.</p>';
    return;
  }
  const g = await callApi('/api/attempts/' + encodeURIComponent(id) + '/migration-guide',
    { method: 'GET' }, 'migrationOut');
  if (!g) return;
  let html = '<p><b>' + esc(g.service) + '</b> ' + esc(g.version || '')
    + ' — attempt state: ' + stateBadge(g.state) + '</p><p class="muted">' + esc(g.note) + '</p>';
  if (!g.steps.length) {
    document.getElementById('migrationOut').innerHTML = html;
    return;
  }
  html += '<table><tr><th>Severity</th><th>Code</th><th>Location</th><th>Field</th><th>Action</th><th>Consumers</th></tr>';
  for (const s of g.steps) {
    html += '<tr><td>' + severityBadge(s.severity) + '</td><td><code>' + esc(s.code)
      + '</code></td><td>' + esc(s.location) + '</td><td><code>' + esc(s.fieldPath)
      + '</code></td><td>' + esc(s.action) + '</td><td>'
      + (s.consumers.length ? esc(s.consumers.join(', ')) : '<span class="muted">—</span>')
      + '</td></tr>';
  }
  html += '</table>';
  document.getElementById('migrationOut').innerHTML = html;
});

