347:             jdbc.update("""
348:                             INSERT INTO spec_versions (service_id, version, source_sha, source_filename,
349:                                 raw_yaml, canonical_json, effective_json, state, published_by)
350:                             VALUES (?, ?, ?, ?, ?, ?, ?, 'published', ?)
351:                             """,
352:                     serviceId, version, sourceSha, sourceFilename, rawYaml, canonicalJson,
353:                     effectiveJson, actor);
