15: /**
16:  * Compatibility engine: diffs two EFFECTIVE wire-contract maps produced by the specs
17:  * module (key = "VERB /pathShape :: scope", value = canonical expanded schema JSON).
18:  * It deliberately knows nothing about YAML, $refs, consumers or versions — the specs
19:  * module has already resolved and canonicalized everything.
20:  *
21:  * Semantics follow the guarantee-asymmetry principle (PLAN.md §6):
22:  * - REQUEST side: the space of accepted requests may only grow. Narrowing
23:  *   (required added, property removed, enum/type/constraint tightened) is BREAKING.
24:  * - RESPONSE side: the guaranteed response space may only grow in promise.
25:  *   Weakened guarantees (required removed, property removed, enum/type widened)
26:  *   are BREAKING; strengthened guarantees are INFO.
27:  * - Cosmetic reorganization never reaches this engine: equal effective maps
28:  *   (renamed components, inlined objects, renamed path parameters) produce ZERO findings.
29:  */
30: public final class CompatibilityEngine {
31: 
32:     private static final JsonMapper JSON = JsonMapper.builder().build();
33: 
34:     /** Constraint keys with directional tightness semantics (see {@link #tightness}). */
35:     private static final List<String> CONSTRAINT_KEYS = List.of(
36:             "minimum", "maximum", "minLength", "maxLength", "minItems", "maxItems",
37:             "pattern", "multipleOf", "exclusiveMinimum", "exclusiveMaximum", "uniqueItems");
38: 
39:     /** +1 = new value is tighter, -1 = looser, 0 = no directional change. */
40:     private static int tightness(String key, JsonNode oldValue, JsonNode newValue) {
41:         return switch (key) {
42:             case "minimum", "minLength", "minItems" -> Double.compare(num(newValue), num(oldValue));
43:             case "maximum", "maxLength", "maxItems" -> Double.compare(num(oldValue), num(newValue));
44:             case "pattern", "multipleOf" -> 1;
45:             case "exclusiveMinimum", "exclusiveMaximum", "uniqueItems" ->
46:                     newValue.booleanValue() && !oldValue.booleanValue() ? 1
47:                             : oldValue.booleanValue() && !newValue.booleanValue() ? -1 : 0;
48:             default -> 0;
49:         };
50:     }
51: 
52:     private static double num(JsonNode node) {
53:         return node.isNumber() ? node.numberValue().doubleValue() : 0d;
54:     }
