56:     // ------------------------------------------------------------------ entry point
57: 
58:     public List<CompatibilityFinding> diff(Map<String, String> oldEffective,
59:                                            Map<String, String> newEffective) {
60:         return diff(oldEffective, newEffective, Map.of(), Map.of());
61:     }
62: 
63:     /**
64:      * @param oldPathAliases shape → raw path for the OLD spec (display only)
65:      * @param newPathAliases shape → raw path for the NEW spec (preferred for display)
66:      */
67:     public List<CompatibilityFinding> diff(Map<String, String> oldEffective,
68:                                            Map<String, String> newEffective,
69:                                            Map<String, String> oldPathAliases,
70:                                            Map<String, String> newPathAliases) {
71:         List<CompatibilityFinding> out = new ArrayList<>();
72:         Map<LocationKeys.Operation, Map<String, String>> oldOps = groupByOperation(oldEffective);
73:         Map<LocationKeys.Operation, Map<String, String>> newOps = groupByOperation(newEffective);
74: 
75:         TreeSet<LocationKeys.Operation> operations = new TreeSet<>();
76:         operations.addAll(oldOps.keySet());
77:         operations.addAll(newOps.keySet());
78: 
79:         for (LocationKeys.Operation op : operations) {
80:             Map<String, String> oldScopes = oldOps.get(op);
81:             Map<String, String> newScopes = newOps.get(op);
82:             String path = displayPath(op.shape(), oldPathAliases, newPathAliases);
83:             if (oldScopes == null) {
84:                 out.add(new CompatibilityFinding("OPERATION.ADDED", Severity.INFO, "OPERATION",
85:                         op.verb(), path, op.verb() + " " + op.shape(), null,
86:                         "new operation", null, null));
87:                 continue;
88:             }
89:             if (newScopes == null) {
90:                 out.add(new CompatibilityFinding("OPERATION.REMOVED", Severity.BREAKING, "OPERATION",
91:                         op.verb(), path, op.verb() + " " + op.shape(), null,
92:                         "operation removed; dropped wire locations: "
93:                                 + String.join(", ", new TreeMap<>(oldScopes).keySet()),
94:                         null, null));
95:                 continue;
96:             }
97:             diffOperation(op, path, oldScopes, newScopes, out);
98:         }
99: 
100:         out.sort(Comparator
101:                 .comparing(CompatibilityFinding::location, Comparator.nullsLast(String::compareTo))
102:                 .thenComparing(CompatibilityFinding::fieldPath, Comparator.nullsLast(String::compareTo))
103:                 .thenComparing(CompatibilityFinding::code));
104:         return List.copyOf(out);
105:     }
106: 
107:     private static String displayPath(String shape, Map<String, String> oldAliases,
108:                                       Map<String, String> newAliases) {
109:         String alias = newAliases.get(shape);
110:         if (alias == null) {
111:             alias = oldAliases.get(shape);
112:         }
113:         return alias != null ? alias : shape;
114:     }
115: 
116:     private static Map<LocationKeys.Operation, Map<String, String>> groupByOperation(
117:             Map<String, String> effective) {
118:         Map<LocationKeys.Operation, Map<String, String>> ops = new TreeMap<>();
119:         effective.forEach((key, value) ->
120:                 ops.computeIfAbsent(LocationKeys.operationOf(key), op -> new TreeMap<>())
121:                         .put(key, value));
122:         return ops;
123:     }
