125:     // ------------------------------------------------------------------ per operation
126: 
127:     private void diffOperation(LocationKeys.Operation op, String path,
128:                                Map<String, String> oldScopes, Map<String, String> newScopes,
129:                                List<CompatibilityFinding> out) {
130:         diffRequestBodies(op, path, oldScopes, newScopes, out);
131:         diffParameters(op, path, oldScopes, newScopes, out);
132:         diffResponses(op, path, oldScopes, newScopes, out);
133:     }
134: 
135:     private void diffRequestBodies(LocationKeys.Operation op, String path,
136:                                    Map<String, String> oldScopes, Map<String, String> newScopes,
137:                                    List<CompatibilityFinding> out) {
138:         Map<String, String> oldBodies = filterByPrefix(oldScopes, "requestBody");
139:         Map<String, String> newBodies = filterByPrefix(newScopes, "requestBody");
140:         Map<String, String> oldByMedia = new TreeMap<>();
141:         oldBodies.forEach((key, value) -> oldByMedia.put(LocationKeys.requestBodyMedia(LocationKeys.scopeOf(key)), value));
142:         Map<String, String> newByMedia = new TreeMap<>();
143:         newBodies.forEach((key, value) -> newByMedia.put(LocationKeys.requestBodyMedia(LocationKeys.scopeOf(key)), value));
144: 
145:         for (Map.Entry<String, String> media : oldByMedia.entrySet()) {
146:             if (!newByMedia.containsKey(media.getKey())) {
147:                 out.add(bodyFinding(op, path, "REQUEST_BODY.REMOVED", Severity.BREAKING, media.getKey(),
148:                         "request body media type '" + media.getKey() + "' removed", media.getValue(), null));
149:             }
150:         }
151:         for (Map.Entry<String, String> media : newByMedia.entrySet()) {
152:             String oldJson = oldByMedia.get(media.getKey());
153:             if (oldJson == null) {
154:                 out.add(bodyFinding(op, path, "REQUEST_BODY.ADDED", Severity.INFO, media.getKey(),
155:                         "request body media type '" + media.getKey() + "' added", null, media.getValue()));
156:             } else {
157:                 diffSchema(op, path, bodyLocation(op, media.getKey()), SchemaSide.REQUEST,
158:                         oldJson, media.getValue(), "", out);
159:             }
160:         }
161:     }
162: 
163:     /**
164:      * Parameters are matched by (in, ordinal) — the specs module drops parameter NAMES
165:      * from the effective envelope precisely so that a parameter rename stays invisible.
166:      * This assumes stable parameter ordering within an operation (true for the kit and
167:      * for specifications that append rather than reorder parameters).
168:      */
169:     private void diffParameters(LocationKeys.Operation op, String path,
170:                                 Map<String, String> oldScopes, Map<String, String> newScopes,
171:                                 List<CompatibilityFinding> out) {
172:         Map<String, String> oldParams = filterByPrefix(oldScopes, "param:");
173:         Map<String, String> newParams = filterByPrefix(newScopes, "param:");
174: 
175:         for (Map.Entry<String, String> param : oldParams.entrySet()) {
176:             if (!newParams.containsKey(param.getKey())) {
177:                 out.add(new CompatibilityFinding("PARAM.REMOVED", Severity.BREAKING, "PARAM",
178:                         op.verb(), path, param.getKey(), null,
179:                         "parameter removed", param.getValue(), null));
180:             }
181:         }
182:         for (Map.Entry<String, String> param : newParams.entrySet()) {
183:             String oldJson = oldParams.get(param.getKey());
184:             if (oldJson == null) {
185:                 boolean required = envelopeRequired(param.getValue());
186:                 out.add(new CompatibilityFinding(
187:                         required ? "PARAM.REQUIRED_ADDED" : "PARAM.ADDED_OPTIONAL",
188:                         required ? Severity.BREAKING : Severity.INFO, "PARAM",
189:                         op.verb(), path, param.getKey(), null,
190:                         required ? "new parameter that is required" : "new optional parameter",
191:                         null, param.getValue()));
192:             } else {
193:                 diffParamEnvelope(op, path, param.getKey(), oldJson, param.getValue(), out);
194:             }
195:         }
196:     }
197: 
198:     /** Reads the "required" flag from a parameter envelope JSON produced by the specs module. */
199:     private static boolean envelopeRequired(String envelopeJson) {
200:         JsonNode envelope = parseJson(envelopeJson);
201:         return boolValue(envelope, "required");
202:     }
203: 
204:     private void diffParamEnvelope(LocationKeys.Operation op, String path, String locationKey,
205:                                    String oldJson, String newJson, List<CompatibilityFinding> out) {
206:         JsonNode oldEnvelope = parseJson(oldJson);
207:         JsonNode newEnvelope = parseJson(newJson);
208:         boolean oldRequired = boolValue(oldEnvelope, "required");
209:         boolean newRequired = boolValue(newEnvelope, "required");
210:         if (newRequired && !oldRequired) {
211:             out.add(new CompatibilityFinding("PARAM.REQUIRED_ADDED", Severity.BREAKING, "PARAM",
212:                     op.verb(), path, locationKey, null,
213:                     "parameter became required", oldJson, newJson));
214:         } else if (oldRequired && !newRequired) {
215:             out.add(new CompatibilityFinding("PARAM.REQUIRED_REMOVED", Severity.INFO, "PARAM",
216:                     op.verb(), path, locationKey, null,
217:                     "parameter is no longer required", oldJson, newJson));
218:         }
219:         JsonNode oldSchema = oldEnvelope.get("schema");
220:         JsonNode newSchema = newEnvelope.get("schema");
221:         if (isNullish(oldSchema) && !isNullish(newSchema)) {
222:             out.add(new CompatibilityFinding("REQ.SCHEMA_ADDED", Severity.INFO, "PARAM",
223:                     op.verb(), path, locationKey, null,
224:                     "parameter schema added", null, JsonWriter.write(newSchema)));
225:         } else if (!isNullish(oldSchema) && isNullish(newSchema)) {
226:             out.add(new CompatibilityFinding("REQ.SCHEMA_REMOVED", Severity.BREAKING, "PARAM",
227:                     op.verb(), path, locationKey, null,
228:                     "parameter schema removed", JsonWriter.write(oldSchema), null));
229:         } else if (!isNullish(oldSchema)) {
230:             diffSchemaNode(op, path, locationKey, SchemaSide.REQUEST, oldSchema, newSchema, "", out);
231:         }
232:     }
