234:     private void diffResponses(LocationKeys.Operation op, String path,
235:                                Map<String, String> oldScopes, Map<String, String> newScopes,
236:                                List<CompatibilityFinding> out) {
237:         Map<String, Map<String, String>> oldByStatus = groupResponses(oldScopes);
238:         Map<String, Map<String, String>> newByStatus = groupResponses(newScopes);
239: 
240:         TreeSet<String> statuses = new TreeSet<>();
241:         statuses.addAll(oldByStatus.keySet());
242:         statuses.addAll(newByStatus.keySet());
243: 
244:         for (String status : statuses) {
245:             Map<String, String> oldMedia = oldByStatus.get(status);
246:             Map<String, String> newMedia = newByStatus.get(status);
247:             if (oldMedia == null) {
248:                 out.add(responseFinding(op, path, "RESP.RESPONSE_ADDED", Severity.INFO, status, null,
249:                         "new documented response '" + status + "'", null, firstValue(newMedia)));
250:                 continue;
251:             }
252:             if (newMedia == null) {
253:                 out.add(responseFinding(op, path, "RESP.RESPONSE_REMOVED", Severity.BREAKING, status, null,
254:                         "documented response '" + status + "' removed", firstValue(oldMedia), null));
255:                 continue;
256:             }
257:             boolean oldSchemaless = oldMedia.size() == 1 && oldMedia.containsKey("");
258:             boolean newSchemaless = newMedia.size() == 1 && newMedia.containsKey("");
259:             if (oldSchemaless && !newSchemaless) {
260:                 out.add(responseFinding(op, path, "RESP.RESPONSE_SCHEMA_ADDED", Severity.INFO, status, null,
261:                         "response '" + status + "' now documents a body", null,
262:                         firstValue(newMedia)));
263:                 continue;
264:             }
265:             if (newSchemaless && !oldSchemaless) {
266:                 out.add(responseFinding(op, path, "RESP.MEDIA_TYPE_REMOVED", Severity.BREAKING, status, null,
267:                         "response '" + status + "' no longer documents a body", firstValue(oldMedia), null));
268:                 continue;
269:             }
270:             for (Map.Entry<String, String> media : oldMedia.entrySet()) {
271:                 if (media.getKey().isEmpty()) {
272:                     continue;
273:                 }
274:                 if (!newMedia.containsKey(media.getKey())) {
275:                     out.add(responseFinding(op, path, "RESP.MEDIA_TYPE_REMOVED", Severity.BREAKING, status,
276:                             media.getKey(),
277:                             "response media type '" + media.getKey() + "' removed", media.getValue(), null));
278:                 }
279:             }
280:             for (Map.Entry<String, String> media : newMedia.entrySet()) {
281:                 if (media.getKey().isEmpty()) {
282:                     continue;
283:                 }
284:                 String oldJson = oldMedia.get(media.getKey());
285:                 if (oldJson == null) {
286:                     out.add(responseFinding(op, path, "RESP.MEDIA_TYPE_ADDED", Severity.INFO, status,
287:                             media.getKey(), "response media type '" + media.getKey() + "' added",
288:                             null, media.getValue()));
289:                 } else {
290:                     diffSchema(op, path, responseLocation(op, status, media.getKey()),
291:                             SchemaSide.RESPONSE, oldJson, media.getValue(), "", out);
292:                 }
293:             }
294:         }
295:     }
