297:     private static Map<String, Map<String, String>> groupResponses(Map<String, String> scopes) {
298:         Map<String, Map<String, String>> byStatus = new TreeMap<>();
299:         scopes.forEach((key, value) -> {
300:             String scope = LocationKeys.scopeOf(key);
301:             if (!LocationKeys.isResponse(scope)) {
302:                 return;
303:             }
304:             String status = LocationKeys.responseStatus(scope);
305:             String media = LocationKeys.responseMedia(scope);
306:             byStatus.computeIfAbsent(status, s -> new TreeMap<>()).put(media, value);
307:         });
308:         return byStatus;
309:     }
310: 
311:     private static String firstValue(Map<String, String> mediaMap) {
312:         return mediaMap == null || mediaMap.isEmpty() ? null : mediaMap.values().iterator().next();
313:     }
314: 
315:     private static Map<String, String> filterByPrefix(Map<String, String> scopes, String prefix) {
316:         Map<String, String> out = new TreeMap<>();
317:         scopes.forEach((key, value) -> {
318:             String scope = LocationKeys.scopeOf(key);
319:             if (scope.startsWith(prefix)) {
320:                 out.put(key, value);
321:             }
322:         });
323:         return out;
324:     }
