326:     // ------------------------------------------------------------------ schema level
327: 
328:     private void diffSchema(LocationKeys.Operation op, String path, String locationKey,
329:                             SchemaSide side, String oldJson, String newJson, String fieldPath,
330:                             List<CompatibilityFinding> out) {
331:         JsonNode oldNode = parseJson(oldJson);
332:         JsonNode newNode = parseJson(newJson);
333:         boolean oldNull = isNullish(oldNode);
334:         boolean newNull = isNullish(newNode);
335:         if (oldNull && newNull) {
336:             return;
337:         }
338:         if (oldNull) {
339:             out.add(new CompatibilityFinding(side.prefix() + ".SCHEMA_ADDED", Severity.INFO,
340:                     side.name(), op.verb(), path, locationKey, fieldPath,
341:                     "schema added where none was documented", null, JsonWriter.write(newNode)));
342:             return;
343:         }
344:         if (newNull) {
345:             out.add(new CompatibilityFinding(side.prefix() + ".SCHEMA_REMOVED", Severity.BREAKING,
346:                     side.name(), op.verb(), path, locationKey, fieldPath,
347:                     "documented schema removed", JsonWriter.write(oldNode), null));
348:             return;
349:         }
350:         diffSchemaNode(op, path, locationKey, side, oldNode, newNode, fieldPath, out);
351:     }
352: 
353:     private void diffSchemaNode(LocationKeys.Operation op, String path, String locationKey,
354:                                 SchemaSide side, JsonNode oldNode, JsonNode newNode,
355:                                 String fieldPath, List<CompatibilityFinding> out) {
356:         TypeRelation typeRelation = compareType(op, path, locationKey, side, oldNode, newNode, fieldPath, out);
357:         if (typeRelation == TypeRelation.DISJOINT) {
358:             return; // types diverged entirely; deeper structural comparison would be noise
359:         }
360:         compareEnum(op, path, locationKey, side, oldNode, newNode, fieldPath, out);
361:         compareNullable(op, path, locationKey, side, oldNode, newNode, fieldPath, out);
362:         compareConstraints(op, path, locationKey, side, oldNode, newNode, fieldPath, out);
363:         compareDefault(op, path, locationKey, side, oldNode, newNode, fieldPath, out);
364:         compareProperties(op, path, locationKey, side, oldNode, newNode, fieldPath, out);
365:         compareItems(op, path, locationKey, side, oldNode, newNode, fieldPath, out);
366:         compareCompositions(op, path, locationKey, side, oldNode, newNode, fieldPath, out);
367:     }
368: 
369:     private enum TypeRelation { EQUAL, NARROWED, WIDENED, DISJOINT }
370: 
371:     private TypeRelation compareType(LocationKeys.Operation op, String path, String locationKey,
372:                                      SchemaSide side, JsonNode oldNode, JsonNode newNode,
373:                                      String fieldPath, List<CompatibilityFinding> out) {
374:         Set<String> oldTypes = typeSet(oldNode);
375:         Set<String> newTypes = typeSet(newNode);
376:         if (oldTypes.equals(newTypes)) {
377:             return TypeRelation.EQUAL;
378:         }
379:         TypeRelation relation;
380:         if (oldTypes.isEmpty() || newTypes.isEmpty()) {
381:             relation = oldTypes.isEmpty() ? TypeRelation.NARROWED : TypeRelation.WIDENED;
382:         } else if (oldTypes.containsAll(newTypes)) {
383:             relation = TypeRelation.NARROWED;
384:         } else if (newTypes.containsAll(oldTypes)) {
385:             relation = TypeRelation.WIDENED;
386:         } else {
387:             relation = TypeRelation.DISJOINT;
388:         }
389:         switch (relation) {
390:             case NARROWED -> emit(op, path, locationKey, side, fieldPath,
391:                     "REQ.TYPE_NARROWED", Severity.BREAKING, "RESP.TYPE_NARROWED", Severity.INFO,
392:                     "accepted type(s) narrowed from " + oldTypes + " to " + newTypes,
393:                     JsonWriter.write(oldNode.get("type")), JsonWriter.write(newNode.get("type")), out);
394:             case WIDENED -> emit(op, path, locationKey, side, fieldPath,
395:                     "REQ.TYPE_WIDENED", Severity.INFO, "RESP.TYPE_WIDENED", Severity.BREAKING,
396:                     "accepted type(s) widened from " + oldTypes + " to " + newTypes,
397:                     JsonWriter.write(oldNode.get("type")), JsonWriter.write(newNode.get("type")), out);
398:             case DISJOINT -> emit(op, path, locationKey, side, fieldPath,
399:                     "REQ.TYPE_NARROWED", Severity.BREAKING, "RESP.TYPE_CHANGED", Severity.BREAKING,
400:                     "type changed from " + oldTypes + " to " + newTypes,
401:                     JsonWriter.write(oldNode.get("type")), JsonWriter.write(newNode.get("type")), out);
402:             default -> { /* EQUAL: nothing */ }
403:         }
404:         return relation;
405:     }
406: 
407:     private void compareEnum(LocationKeys.Operation op, String path, String locationKey,
408:                              SchemaSide side, JsonNode oldNode, JsonNode newNode,
409:                              String fieldPath, List<CompatibilityFinding> out) {
410:         Set<String> oldValues = enumSet(oldNode);
411:         Set<String> newValues = enumSet(newNode);
412:         if (oldValues.equals(newValues)) {
413:             return;
414:         }
415:         Set<String> removed = difference(oldValues, newValues);
416:         Set<String> added = difference(newValues, oldValues);
417:         if (!removed.isEmpty()) {
418:             emit(op, path, locationKey, side, fieldPath,
419:                     "REQ.ENUM_NARROWED", Severity.BREAKING, "RESP.ENUM_NARROWED", Severity.INFO,
420:                     "enum value(s) removed: " + removed,
421:                     JsonWriter.write(oldNode.get("enum")), JsonWriter.write(newNode.get("enum")), out);
422:         }
423:         if (!added.isEmpty()) {
424:             emit(op, path, locationKey, side, fieldPath,
425:                     "REQ.ENUM_WIDENED", Severity.INFO, "RESP.ENUM_WIDENED", Severity.BREAKING,
426:                     "enum value(s) added: " + added,
427:                     JsonWriter.write(oldNode.get("enum")), JsonWriter.write(newNode.get("enum")), out);
428:         }
429:     }
430: 
431:     private void compareNullable(LocationKeys.Operation op, String path, String locationKey,
432:                                  SchemaSide side, JsonNode oldNode, JsonNode newNode,
433:                                  String fieldPath, List<CompatibilityFinding> out) {
434:         boolean oldNullable = boolValue(oldNode, "nullable");
435:         boolean newNullable = boolValue(newNode, "nullable");
436:         if (oldNullable == newNullable) {
437:             return;
438:         }
439:         if (newNullable) {
440:             emit(op, path, locationKey, side, fieldPath,
441:                     "REQ.TYPE_WIDENED", Severity.INFO, "RESP.NULLABLE_ADDED", Severity.BREAKING,
442:                     "null values are now accepted",
443:                     JsonWriter.write(oldNode.get("nullable")), JsonWriter.write(newNode.get("nullable")), out);
444:         } else {
445:             emit(op, path, locationKey, side, fieldPath,
446:                     "REQ.CONSTRAINT_TIGHTENED", Severity.BREAKING, "RESP.CONSTRAINT_TIGHTENED", Severity.INFO,
447:                     "null values are no longer accepted",
448:                     JsonWriter.write(oldNode.get("nullable")), JsonWriter.write(newNode.get("nullable")), out);
449:         }
450:     }
451: 
452:     private void compareConstraints(LocationKeys.Operation op, String path, String locationKey,
453:                                     SchemaSide side, JsonNode oldNode, JsonNode newNode,
454:                                     String fieldPath, List<CompatibilityFinding> out) {
455:         for (String key : CONSTRAINT_KEYS) {
456:             JsonNode oldValue = oldNode.get(key);
457:             JsonNode newValue = newNode.get(key);
458:             boolean oldPresent = oldValue != null && !isNullish(oldValue);
459:             boolean newPresent = newValue != null && !isNullish(newValue);
460:             if (!oldPresent && !newPresent) {
461:                 continue;
462:             }
463:             if (oldPresent && newPresent && oldValue.equals(newValue)) {
464:                 continue;
465:             }
466:             int direction;
467:             String verb;
468:             if (oldPresent && newPresent) {
469:                 direction = tightness(key, oldValue, newValue);
470:                 verb = "changed";
471:             } else if (newPresent) {
472:                 direction = 1;
473:                 verb = "added";
474:             } else {
475:                 direction = -1;
476:                 verb = "removed";
477:             }
478:             if (direction == 0) {
479:                 continue;
480:             }
481:             String detail = "'" + key + "' " + verb
482:                     + (newPresent ? ": " + JsonWriter.write(newValue) : "")
483:                     + (oldPresent && newPresent ? " (was " + JsonWriter.write(oldValue) + ")" : "");
484:             // Directional codes, mirroring the enum/type rules: tightening breaks senders
485:             // (request), loosening breaks strict readers (response).
486:             boolean tightened = direction > 0;
487:             boolean request = side == SchemaSide.REQUEST;
488:             out.add(new CompatibilityFinding(
489:                     request ? (tightened ? "REQ.CONSTRAINT_TIGHTENED" : "REQ.CONSTRAINT_LOOSENED")
490:                             : (tightened ? "RESP.CONSTRAINT_TIGHTENED" : "RESP.CONSTRAINT_LOOSENED"),
491:                     tightened == request ? Severity.BREAKING : Severity.INFO,
492:                     side.name(), op.verb(), path, locationKey, fieldPath, detail,
493:                     JsonWriter.write(oldValue), JsonWriter.write(newValue)));
494:         }
495:     }
496: 
497:     private void compareDefault(LocationKeys.Operation op, String path, String locationKey,
498:                                 SchemaSide side, JsonNode oldNode, JsonNode newNode,
499:                                 String fieldPath, List<CompatibilityFinding> out) {
500:         if (side != SchemaSide.REQUEST) {
501:             return;
502:         }
503:         JsonNode oldDefault = oldNode.get("default");
504:         JsonNode newDefault = newNode.get("default");
505:         if (oldDefault == null || newDefault == null || oldDefault.equals(newDefault)) {
506:             return;
507:         }
508:         out.add(new CompatibilityFinding("REQ.DEFAULT_CHANGED", Severity.INFO, side.name(),
509:                 op.verb(), path, locationKey, fieldPath,
510:                 "default value changed",
511:                 JsonWriter.write(oldDefault), JsonWriter.write(newDefault)));
512:     }
513: 
514:     /**
515:      * Property sets with rename pairing: a removed property and an added property whose
516:      * canonical schemas are deep-equal are reported once as PROPERTY_RENAMED (breaking)
517:      * instead of REMOVED+ADDED. Unmatched removals/ additions fall back to their own codes.
518:      */
519:     private void compareProperties(LocationKeys.Operation op, String path, String locationKey,
520:                                    SchemaSide side, JsonNode oldNode, JsonNode newNode,
521:                                    String fieldPath, List<CompatibilityFinding> out) {
522:         JsonNode oldProps = oldNode.get("properties");
523:         JsonNode newProps = newNode.get("properties");
524:         Map<String, JsonNode> oldMap = propertyMap(oldProps);
525:         Map<String, JsonNode> newMap = propertyMap(newProps);
526: 
527:         List<String> removed = new ArrayList<>(difference(oldMap.keySet(), newMap.keySet()));
528:         List<String> added = new ArrayList<>(difference(newMap.keySet(), oldMap.keySet()));
529: 
530:         Map<String, String> renames = new LinkedHashMap<>();
531:         for (String oldName : removed) {
532:             String oldCanonical = JsonWriter.write(oldMap.get(oldName));
533:             for (String newName : added) {
534:                 if (JsonWriter.write(newMap.get(newName)).equals(oldCanonical)) {
535:                     renames.put(oldName, newName);
536:                     break;
537:                 }
538:             }
539:         }
540:         renames.keySet().forEach(removed::remove);
