64:                 String slug = serviceDir.getFileName().toString();
65:                 if (store.hasAuditEvent(slug, "KIT_IMPORT")) {
66:                     continue; // already imported on a previous start: never touch user data
67:                 }
68:                 imported++;
69:                 seedService(serviceDir, slug);
70:             }
71:             LOG.info("kit import: {} service(s) seeded from {}", imported, specsDir);
72:         } catch (IOException e) {
73:             LOG.error("kit import failed to read {}: {}", specsDir, e.getMessage(), e);
74:         }
