80:             store.insertAuditEvent(slug, null, null, "SERVICE_REGISTERED", "registered",
81:                     "kit-importer", null, "service registered during starter kit import");
82:         }
83:         Map<String, Integer> outcomes = new LinkedHashMap<>();
84:         List<String> fileNotes = new java.util.ArrayList<>();
85:         try (Stream<Path> files = Files.list(serviceDir)) {
86:             List<Path> yamlFiles = files.filter(p -> {
87:                 String name = p.getFileName().toString().toLowerCase();
88:                 return name.endsWith(".yaml") || name.endsWith(".yml");
89:             }).sorted(Comparator.comparing(p -> p.getFileName().toString())).toList();
