20: /**
21:  * Matches compatibility findings against declared consumer usage (PLAN.md §7).
22:  *
23:  * Matching is strictly structured — no substring matching anywhere:
24:  * - bindings join findings by service slug + HTTP method + path SHAPE (placeholder
25:  *   names are normalized by the shared specs module, so {@code /quotes/{id}} matches
26:  *   {@code /quotes/{quoteId}});
27:  * - request-side findings join {@code sends}, response-side findings join {@code reads};
28:  * - field paths compare as SEGMENT LISTS (dots and {@code []} items), overlapping when
29:  *   one path is a segment-prefix of the other ({@code premium} overlaps
30:  *   {@code premium.breakdown[].amount}; sibling {@code premium.total} does not);
31:  * - renamed properties are matched against BOTH the old path (finding.fieldPath) and
32:  *   the new path (derived from the finding detail);
33:  * - parameter findings are resolved to names via the specs module's param-name index
34:  *   (old spec for removals, new spec for additions/required flips).
35:  *
36:  * Tier semantics (PLAN.md §6/§7 + policy):
37:  * - AFFECTED: declared usage directly overlaps a breaking change (or the changed
38:  *   element is operation-wide), or a now-required element is provably not sent.
39:  * - POSSIBLE: the consumer uses the affected operation but its declarations cannot
40:  *   prove or rule out dependence; also the advisory tier for response-side widening
41:  *   (new enum/type values) hit by declared readers — files cannot express exhaustive
42:  *   value matching.
43:  * - NONE: independence is provable (declared usage excludes the changed element) or
44:  *   nothing declared is relevant. Non-breaking findings never rise above NONE.
45:  */
46: public class ConsumerImpactAnalyzer {
47: 
48:     /**
49:      * Breaking response-side findings whose damage depends on the consumer's value
50:      * handling, which files cannot declare → declared readers land in POSSIBLE.
51:      */
52:     private static final Set<String> WIDENING_CODES = Set.of(
53:             "RESP.ENUM_WIDENED", "RESP.TYPE_WIDENED", "RESP.CONSTRAINT_LOOSENED", "RESP.NULLABLE_ADDED");
54: 
55:     private static final Pattern RENAME_IN_DETAIL = Pattern.compile("'(.+?)' renamed to '(.+?)'");
56: 
57:     /**
58:      * @param service       provider service slug the findings belong to (e.g. "quote-api")
59:      * @param oldDoc        previously published spec (param-name index for removals)
60:      * @param newDoc        candidate spec (param-name index for additions/required flips)
61:      * @param findings      compatibility findings old→new (engine output, any order)
62:      * @param consumers     all registered consumers
63:      */
64:     public ImpactSummary analyze(String service, SpecDocument oldDoc, SpecDocument newDoc,
65:                                  List<CompatibilityFinding> findings,
66:                                  List<ConsumerDeclaration> consumers) {
67:         List<ConsumerImpact> perConsumer = consumers.stream()
68:                 .sorted(java.util.Comparator.comparing(ConsumerDeclaration::name))
69:                 .map(consumer -> analyzeConsumer(service, oldDoc, newDoc, findings, consumer))
70:                 .toList();
71: 
72:         int affected = 0;
73:         int possible = 0;
74:         for (ConsumerImpact impact : perConsumer) {
75:             switch (impact.level()) {
76:                 case AFFECTED -> affected++;
77:                 case POSSIBLE -> possible++;
78:                 default -> { /* NONE */ }
79:             }
80:         }
81:         return new ImpactSummary(service, oldDoc.getSpecVersion(), newDoc.getSpecVersion(),
82:                 perConsumer, affected, possible, perConsumer.size() - affected - possible);
83:     }
84: 
85:     private ConsumerImpact analyzeConsumer(String service, SpecDocument oldDoc, SpecDocument newDoc,
86:                                            List<CompatibilityFinding> findings,
87:                                            ConsumerDeclaration consumer) {
88:         List<DeclaredOperation> bindings = consumer.forProvider(service);
89:         List<String> operations = bindings.stream().map(DeclaredOperation::display).sorted().toList();
90: 
91:         Set<FindingImpact> unique = new LinkedHashSet<>();
92:         for (CompatibilityFinding finding : findings) {
93:             for (DeclaredOperation binding : bindings) {
94:                 classify(service, oldDoc, newDoc, finding, binding).ifPresent(unique::add);
95:             }
96:         }
97:         List<FindingImpact> impacts = List.copyOf(unique);
98:         ImpactLevel level = impacts.stream()
99:                 .map(FindingImpact::level)
100:                 .reduce(ImpactLevel::worst)
101:                 .orElse(ImpactLevel.NONE);
102: 
103:         String reason;
104:         if (impacts.isEmpty()) {
105:             reason = operations.isEmpty()
106:                     ? "declares no usage of '" + service + "'"
107:                     : "declared usage of '" + service + "' (" + String.join(", ", operations)
108:                             + ") is not touched by any compatibility finding";
109:         } else {
110:             reason = switch (level) {
111:                 case AFFECTED -> "declared usage directly overlaps breaking change(s)";
112:                 case POSSIBLE -> "declared usage may depend on changed element(s) - see findings";
113:                 case NONE -> "no breaking impact on declared usage";
114:             };
115:         }
116:         return new ConsumerImpact(consumer.name(), consumer.team(), level, operations, impacts, reason);
117:     }
118: 
119:     // ------------------------------------------------------------------ classification
120: 
121:     private Optional<FindingImpact> classify(String service, SpecDocument oldDoc, SpecDocument newDoc,
122:                                              CompatibilityFinding f, DeclaredOperation binding) {
123:         // Structured join: same service slug, same method, same path shape. Never substring.
124:         LocationKeys.Operation op = LocationKeys.operationOf(f.location());
125:         if (!binding.provider().equals(service)
126:                 || !binding.method().equals(f.method())
127:                 || !binding.pathShape().equals(op.shape())) {
128:             return Optional.empty();
129:         }
130:         boolean breaking = f.severity() == Severity.BREAKING;
131:         if ("CONSUMERS".equalsIgnoreCase(f.scope())) {
132:             return Optional.of(driftImpact(f, binding));
133:         }
134:         if (!breaking) {
135:             return Optional.of(none(f, "informational change (" + f.detail()
136:                     + ") - non-breaking, no consumer impact"));
137:         }
138:         return switch (f.scope()) {
139:             case "OPERATION" -> Optional.of(affected(f,
140:                     "operation " + f.method() + " " + f.path() + " that you call was removed"));
141:             case "REQUEST_BODY" -> Optional.of(affected(f,
142:                     "the request contract of " + f.method() + " " + f.path() + " changed: " + f.detail()));
143:             case "PARAM" -> Optional.of(paramImpact(f, binding, oldDoc, newDoc));
144:             case "REQUEST" -> Optional.of(requestImpact(f, binding));
145:             case "RESPONSE" -> Optional.of(responseImpact(f, binding));
146:             default -> Optional.of(possible(f, "unhandled finding scope '" + f.scope()
147:                     + "' - manual review required"));
148:         };
149:     }
150: 
151:     // ------------------------------------------------------------------ consumer-drift findings
152: 
153:     /**
154:      * Findings from the {@link ConsumerDriftScanner} (scope {@code consumers:*}) are
155:      * advisory by design: they name declarations that no longer match the incoming spec,
156:      * which may be accepted history rather than damage from this candidate. The declared
157:      * overlap proves the consumer still references the drifted element → POSSIBLE.
158:      */
159:     private FindingImpact driftImpact(CompatibilityFinding f, DeclaredOperation binding) {
160:         if (f.fieldPath() == null || f.fieldPath().isBlank()) {
161:             return possible(f, "you declare " + binding.display()
162:                     + ", but the incoming spec contains no matching operation"
163:                     + " (update or re-upload the consumer declaration)");
164:         }
165:         // the reads/sends kind is encoded in the finding's location (scope is CONSUMERS)
166:         boolean reads = f.location() != null && f.location().contains("consumers:reads");
167:         List<String> declared = reads ? binding.reads() : binding.sends();
168:         String overlap = firstOverlap(declared, f.fieldPath(), null);
169:         String kind = reads ? "read" : "send";
170:         if (overlap != null) {
171:             return possible(f, "you " + kind + " '" + overlap + "' on " + f.method() + " "
172:                     + f.path() + ", which the incoming spec no longer documents"
173:                     + " (declaration predates the current contract)");
174:         }
175:         return none(f, "no declared " + kind + " of '" + f.fieldPath() + "' on "
176:                 + f.method() + " " + f.path() + " — this drift concerns other consumers");
177:     }
178: 
179:     // ------------------------------------------------------------------ parameters
180: 
181:     private FindingImpact paramImpact(CompatibilityFinding f, DeclaredOperation binding,
182:                                       SpecDocument oldDoc, SpecDocument newDoc) {
183:         // The engine's envelopes deliberately drop parameter names; the specs module's
184:         // name index restores them (old spec for removals, new spec for additions).
185:         String oldName = oldDoc.getParamNames().get(f.location());
186:         String newName = newDoc.getParamNames().get(f.location());
187:         boolean added = f.code().equals("PARAM.REQUIRED_ADDED");
188:         String name = added ? (newName != null ? newName : oldName)
189:                 : (oldName != null ? oldName : newName);
190:         if (name == null) {
191:             return possible(f, "parameter at '" + f.location() + "' changed ("
192:                     + f.detail() + ") but its name cannot be resolved from the specifications;"
193:                     + " whether you send it is unknown");
194:         }
195:         boolean declared = binding.sends().contains(name);
196:         if (added) {
197:             if (declared) {
198:                 return none(f, "already declares sending parameter '" + name + "'");
199:             }
200:             return affected(f, "'" + name + "' is now required on " + f.method() + " " + f.path()
201:                     + " but is not declared in sends");
202:         }
203:         // PARAM.REMOVED
204:         if (declared) {
205:             return affected(f, "you send parameter '" + name + "', which was removed from "
206:                     + f.method() + " " + f.path());
207:         }
208:         return none(f, "does not declare sending parameter '" + name + "'");
209:     }
210: 
211:     // ------------------------------------------------------------------ request side
212: 
213:     private FindingImpact requestImpact(CompatibilityFinding f, DeclaredOperation binding) {
214:         String field = f.fieldPath();
215:         if (field == null || field.isBlank()) {
216:             return affected(f, "the documented request schema of " + f.method() + " " + f.path()
217:                     + " changed: " + f.detail());
218:         }
219:         if (f.code().equals("REQ.REQUIRED_ADDED")) {
220:             return requiredAddedImpact(f, binding, field);
221:         }
222:         String newPath = renameNewPath(f);
223:         String overlapPath = firstOverlap(binding.sends(), field, newPath);
224:         if (overlapPath != null) {
225:             String caveat = f.code().equals("REQ.ENUM_NARROWED")
226:                     ? " (sent values are not recorded in the consumer file, so a sent value may be"
227:                             + " one of the removed ones: " + f.detail() + ")"
228:                     : "";
229:             return affected(f, "you send '" + overlapPath + "' on " + f.method() + " " + f.path()
230:                     + ", which " + codePhrase(f.code(), field, newPath) + caveat);
231:         }
232:         if (binding.sends().isEmpty()) {
233:             return possible(f, "you call " + f.method() + " " + f.path() + " but declare no request"
234:                     + " fields; dependence on '" + field + "' cannot be ruled out");
235:         }
236:         return none(f, "declared sends on " + f.method() + " " + f.path() + " do not include '"
237:                 + field + "'");
238:     }
239: 
240:     /**
241:      * REQ.REQUIRED_ADDED inverts the usual overlap logic: declaring the field proves
242:      * compliance (NONE); declaring only a containing object is genuinely unknown
243:      * (POSSIBLE); proving the field is NOT sent while it becomes mandatory is AFFECTED.
244:      */
245:     private FindingImpact requiredAddedImpact(CompatibilityFinding f, DeclaredOperation binding,
246:                                               String field) {
247:         // Declaring the field itself (or a subfield of it — sending a subfield implies
248:         // sending its parent object) proves the required element is already sent.
249:         for (String send : binding.sends()) {
250:             if (isPrefixOrEqual(segments(field), segments(send))) {
251:                 return none(f, "already declares sending '" + send + "'");
252:             }
253:         }
254:         // Declaring only a containing object: whether it includes the field is unknown.
255:         for (String send : binding.sends()) {
256:             if (isPrefixOrEqual(segments(send), segments(field))) {
257:                 return possible(f, "you declare sending '" + send + "', which may or may not include"
258:                         + " the now-required '" + field + "'");
259:             }
260:         }
261:         return affected(f, "'" + field + "' is now required on " + f.method() + " " + f.path()
262:                 + " but is not declared in sends");
263:     }
264: 
265:     // ------------------------------------------------------------------ response side
266: 
267:     private FindingImpact responseImpact(CompatibilityFinding f, DeclaredOperation binding) {
268:         String field = f.fieldPath();
269:         if (field == null || field.isBlank()) {
270:             return affected(f, "the documented response of " + f.method() + " " + f.path()
271:                     + " changed: " + f.detail());
272:         }
273:         String newPath = renameNewPath(f);
274:         String overlapPath = firstOverlap(binding.reads(), field, newPath);
275:         if (overlapPath != null) {
276:             if (WIDENING_CODES.contains(f.code())) {
277:                 return possible(f, "you read '" + overlapPath + "' on " + f.method() + " " + f.path()
278:                         + "; the server may return values your matching does not handle ("
279:                         + f.detail() + ")");
280:             }
281:             return affected(f, "you read '" + overlapPath + "' on " + f.method() + " " + f.path()
282:                     + ", which " + codePhrase(f.code(), field, newPath));
283:         }
284:         if (binding.reads().isEmpty()) {
285:             return possible(f, "you call " + f.method() + " " + f.path() + " but declare no response"
286:                     + " fields; dependence on '" + field + "' cannot be ruled out");
287:         }
288:         return none(f, "declared reads on " + f.method() + " " + f.path() + " do not include '"
289:                 + field + "'");
290:     }
291: 
292:     // ------------------------------------------------------------------ path helpers
293: 
294:     /**
295:      * First declared path overlapping the finding's old or new path: overlap means one
296:      * segment list is a prefix of the other ({@code []} markers are equated with their
297:      * parent segment, so an array and its items belong to one lineage). Returns the
298:      * DECLARED path for use in the reason text, or null.
299:      */
300:     private static String firstOverlap(List<String> declared, String oldPath, String newPath) {
301:         for (String candidate : declared) {
302:             if (overlaps(candidate, oldPath) || (newPath != null && overlaps(candidate, newPath))) {
303:                 return candidate;
304:             }
305:         }
306:         return null;
307:     }
308: 
309:     private static boolean overlaps(String a, String b) {
310:         return isPrefixOrEqual(segments(a), segments(b)) || isPrefixOrEqual(segments(b), segments(a));
311:     }
312: 
313:     private static boolean isPrefixOrEqual(List<String> prefix, List<String> longer) {
314:         if (prefix.size() > longer.size()) {
315:             return false;
316:         }
317:         for (int i = 0; i < prefix.size(); i++) {
318:             if (!prefix.get(i).equals(longer.get(i))) {
319:                 return false;
320:             }
321:         }
322:         return true;
323:     }
324: 
325:     /** "premium.breakdown[].amount" → ["premium", "breakdown", "amount"] ([] markers equated). */
326:     private static List<String> segments(String fieldPath) {
327:         String[] parts = fieldPath.split("\\.");
328:         List<String> out = new ArrayList<>(parts.length);
329:         for (String part : parts) {
330:             out.add(part.endsWith("[]") ? part.substring(0, part.length() - 2) : part);
331:         }
332:         return out;
333:     }
334: 
335:     /** For PROPERTY_RENAMED findings: fieldPath with its last segment replaced by the new name. */
336:     private static String renameNewPath(CompatibilityFinding f) {
337:         if (f.fieldPath() == null || !f.code().endsWith("PROPERTY_RENAMED")) {
338:             return null;
339:         }
340:         Matcher m = RENAME_IN_DETAIL.matcher(f.detail() == null ? "" : f.detail());
341:         if (!m.find()) {
342:             return null;
343:         }
344:         int lastDot = f.fieldPath().lastIndexOf('.');
345:         return lastDot < 0 ? m.group(2) : f.fieldPath().substring(0, lastDot + 1) + m.group(2);
346:     }
347: 
348:     /** Short per-code verb phrase for reason texts. */
349:     private static String codePhrase(String code, String field, String newPath) {
350:         return switch (code) {
351:             case "RESP.PROPERTY_REMOVED" -> "was removed from responses";
352:             case "REQ.PROPERTY_REMOVED" -> "was removed from the accepted requests";
353:             case "RESP.REQUIRED_REMOVED" -> "is no longer guaranteed in responses";
354:             case "REQ.REQUIRED_REMOVED" -> "is no longer required in requests";
355:             case "RESP.PROPERTY_RENAMED", "REQ.PROPERTY_RENAMED" ->
356:                     "is renamed to '" + (newPath != null
357:                             ? newPath.substring(newPath.lastIndexOf('.') + 1) : "?") + "'";
358:             case "REQ.ENUM_NARROWED" -> "had accepted enum value(s) removed";
359:             case "REQ.TYPE_NARROWED", "REQ.CONSTRAINT_TIGHTENED" -> "was tightened";
360:             case "RESP.TYPE_CHANGED" -> "changed type";
361:             default -> "changed (" + code + ")";
362:         };
363:     }
364: 
365:     // ------------------------------------------------------------------ impact factories
366: 
367:     private static FindingImpact affected(CompatibilityFinding f, String reason) {
368:         return impact(f, ImpactLevel.AFFECTED, reason);
369:     }
370: 
371:     private static FindingImpact possible(CompatibilityFinding f, String reason) {
372:         return impact(f, ImpactLevel.POSSIBLE, reason);
373:     }
374: 
375:     private static FindingImpact none(CompatibilityFinding f, String reason) {
376:         return impact(f, ImpactLevel.NONE, reason);
377:     }
378: 
379:     private static FindingImpact impact(CompatibilityFinding f, ImpactLevel level, String reason) {
380:         return new FindingImpact(f.code(), f.severity().code(), f.method(), f.path(),
381:                 f.location(), f.fieldPath(), level, reason);
382:     }
383: }

