private JsonNode expandNode(JsonNode node, int depth, String fieldPath, java.util.Deque<String> activeRefs) {
    if (node == null || node.isMissingNode()) return JsonMappers.missingNode();
    if (node.isObject()) {
        JsonNode ref = node.get("$ref");
        if (ref != null && ref.isString() && RefResolver.isLocalRef(ref.stringValue())) {
            String refValue = ref.stringValue();
            java.util.Optional<JsonNode> target = RefResolver.resolve(root, refValue);
            if (target.isEmpty()) {
                return JsonMappers.textNode("$unresolved:" + refValue);
            }
            if (activeRefs.contains(refValue)) {
                // circular reference: represent the cycle by its wire-visible property path
                ObjectNode marker = JsonNodeFactory.instance.objectNode();
                marker.put("x-circular", fieldPath.isEmpty() ? "$" : fieldPath);
                return marker;
            }
            activeRefs.push(refValue);
            JsonNode expanded;
            try { expanded = expandNode(target.get(), depth + 1, fieldPath, activeRefs); }
            finally { activeRefs.pop(); }
            return expanded;
        }
        TreeMap<String, JsonNode> out = new TreeMap<>();
        JsonNode allOfExpanded = null;
        for (entry : node.properties()) {
            key... value...
            if properties → expand each child with childPath(fieldPath, p.getKey())
            else if items/additionalProperties/schema (isObject) → expandNode(value, depth+1, items? fieldPath+"[]" : additionalProperties? fieldPath+"{}" : fieldPath, activeRefs)
            else if allOf/anyOf/oneOf → expandedList = expandSchemaList(value, depth, fieldPath?, activeRefs) — hmm, branches: path for branches: fieldPath + "[i]"? 
            else out.put(key, value)
