127:     private void diffOperation(LocationKeys.Operation op, String path,
128:                                Map<String, String> oldScopes, Map<String, String> newScopes,
129:                                List<CompatibilityFinding> out) {
130:         diffRequestBodies(op, path, oldScopes, newScopes, out);
131:         diffParameters(op, path, oldScopes, newScopes, out);
132:         diffResponses(op, path, oldScopes, newScopes, out);
133:     }
