315:     private static Map<String, String> filterByPrefix(Map<String, String> scopes, String prefix) {
316:         Map<String, String> out = new TreeMap<>();
317:         scopes.forEach((key, value) -> {
318:             String scope = LocationKeys.scopeOf(key);
319:             if (scope.startsWith(prefix)) {
320:                 out.put(key, value);
321:             }
322:         });
323:         return out;
324:     }
