232:     /** Dry-run comparison of two REGISTERED versions; publishes nothing. */
233:     public Map<String, Object> compare(String slug, String fromVersion, String toVersion, String actor) {
234:         RegistryStore.ServiceRow service = requireService(slug);
235:         RegistryStore.SpecVersionRow from = store.findVersion(service.id(), fromVersion)
236:                 .orElseThrow(() -> new NotFoundException("version '" + fromVersion
237:                         + "' of '" + slug + "' is not registered"));
238:         RegistryStore.SpecVersionRow to = store.findVersion(service.id(), toVersion)
239:                 .orElseThrow(() -> new NotFoundException("version '" + toVersion
240:                         + "' of '" + slug + "' is not registered"));
241:         SpecDocument oldDoc = specParser.parse(from.rawYaml());
242:         SpecDocument newDoc = specParser.parse(to.rawYaml());
243:         List<CompatibilityFinding> findings = engine.diff(oldDoc.getEffectiveSchemas(),
244:                 newDoc.getEffectiveSchemas(), oldDoc.getPathAliases(), newDoc.getPathAliases());
245:         findings = appendLifecycleFindings(findings, oldDoc, newDoc);
246:         List<CompatibilityFinding> withDrift = new ArrayList<>(findings);
247:         withDrift.addAll(driftScanner.scan(slug, oldDoc, newDoc, consumerRegistry.all(), findings));
248:         findings = withDrift;
249:         com.contractguard.impact.ImpactSummary summary = impactAnalyzer.analyze(slug, oldDoc,
250:                 newDoc, findings, consumerRegistry.all());
251:         List<PolicyFinding> policyFindings = versionPolicy.analyze(fromVersion, toVersion,
252:                 count(findings, Severity.BREAKING) > 0);
253:         DecisionResult decision = PublishingDecision.evaluate(findings, summary);
254:         store.insertAuditEvent(slug, toVersion, null, "COMPATIBILITY_COMPARE", decision.decision().name(),
255:                 actor, null, "compared registered versions " + fromVersion + " -> " + toVersion + ": "
256:                         + count(findings, Severity.BREAKING) + " breaking finding(s)");
257:         return report(slug, fromVersion, toVersion, new Evaluation(newDoc, fromVersion, findings,
258:                 policyFindings, summary, decision), true);
259:     }
