299:     private Map<String, Object> decide(RegistryStore.AttemptRow attempt, String newState,
300:                                        String actor, String justification, String auditAction,
301:                                        String auditDetails, boolean notify) {
302:         String slug = store.serviceSlug(attempt.serviceId()).orElse("(unknown)");
303:         // the attempt was validated at upload time; re-parse is guaranteed to succeed
304:         SpecDocument doc = specParser.parse(attempt.rawYaml());
305:         String version = doc.getSpecVersion();
306:         // only publish outcomes make the version current; abandon/reject never store one
307:         boolean publishOutcome = "published".equals(newState) || "overridden_published".equals(newState);
308:         store.decideAndPublish(attempt.id(), attempt.serviceId(), slug, version, attempt.state(),
309:                 attempt.sourceSha(), null, attempt.rawYaml(),
310:                 publishOutcome ? doc.getCanonicalJson() : null,
311:                 publishOutcome ? JSON.writeValueAsString(doc.getEffectiveSchemas()) : null,
312:                 newState, actor, justification, auditAction,
313:                 auditDetails + " (version " + version + ")");
314:         if (notify) {
315:             List<String> affected = store.affectedConsumers(attempt.id());
316:             notifier.deliver(newState, slug, version, webhookPayload(newState, slug, version,
317:                     actor, justification, storedFindings(attempt.id()), affected, newState));
318:         }
319:         return attemptDetail(attempt.id());
320:     }
