322:     // ------------------------------------------------------------------ evaluation core
323: 
324:     private Evaluation evaluate(String slug, RegistryStore.SpecVersionRow current, SpecDocument newDoc) {
325:         List<CompatibilityFinding> findings;
326:         SpecDocument oldDoc;
327:         if (current == null) {
328:             oldDoc = newDoc;
329:             findings = List.of();
330:         } else {
331:             oldDoc = specParser.parse(current.rawYaml());
332:             findings = new ArrayList<>(engine.diff(oldDoc.getEffectiveSchemas(),
333:                     newDoc.getEffectiveSchemas(), oldDoc.getPathAliases(), newDoc.getPathAliases()));
334:             findings = appendLifecycleFindings(findings, oldDoc, newDoc);
335:         }
336:         // cumulative consumer-drift scan (A-08 default): declared usage that no longer
337:         // exists in the incoming spec, regardless of WHICH published version removed it;
338:         // drift already explained by this hop's delta findings is suppressed
339:         List<CompatibilityFinding> withDrift = new ArrayList<>(findings);
340:         withDrift.addAll(driftScanner.scan(slug, current == null ? null : oldDoc, newDoc,
341:                 consumerRegistry.all(), findings));
342:         findings = withDrift;
343:         com.contractguard.impact.ImpactSummary summary = impactAnalyzer.analyze(slug, oldDoc,
344:                 newDoc, findings, consumerRegistry.all());
345:         String previousVersion = current == null ? null : current.version();
346:         List<PolicyFinding> policyFindings = versionPolicy.analyze(previousVersion,
347:                 newDoc.getSpecVersion(), count(findings, Severity.BREAKING) > 0);
348:         DecisionResult decision = PublishingDecision.evaluate(findings, summary);
349:         return new Evaluation(newDoc, previousVersion, findings, policyFindings, summary, decision);
350:     }
