352:     /**
353:      * Deprecation lifecycle findings (PLAN.md §6): a newly {@code deprecated} field is a
354:      * warn (non-gating); an {@code x-sunset} date in the past/future while the field is
355:      * still documented is a warn/info. These never gate (severity never BREAKING).
356:      */
357:     private List<CompatibilityFinding> appendLifecycleFindings(List<CompatibilityFinding> findings,
358:                                                                SpecDocument oldDoc, SpecDocument newDoc) {
359:         Set<String> previouslyDeprecated = new TreeSet<>();
360:         for (DeprecationRecord record : oldDoc.getDeprecations()) {
361:             previouslyDeprecated.add(record.humanPath());
362:         }
363:         LocalDate today = LocalDate.now();
364:         for (DeprecationRecord record : newDoc.getDeprecations()) {
365:             String where = record.humanPath();
366:             if (!previouslyDeprecated.contains(where)) {
367:                 findings.add(new CompatibilityFinding("DEPRECATION.ADDED", Severity.WARN, "LIFECYCLE",
368:                         null, null, where, where,
369:                         "field newly marked deprecated"
370:                                 + record.sunsetRaw().map(s -> " (x-sunset: " + s + ")").orElse(""),
371:                         null, null));
372:             }
373:             record.sunset().ifPresent(date -> {
374:                 String code = date.isAfter(today) ? "SUNSET_SCHEDULED" : "SUNSET_PASSED";
375:                 Severity severity = date.isAfter(today) ? Severity.INFO : Severity.WARN;
376:                 String detail = "x-sunset date " + date + (date.isAfter(today)
377:                         ? " is scheduled"
378:                         : " has passed while the field is still documented");
379:                 findings.add(new CompatibilityFinding(code, severity, "LIFECYCLE", null, null,
380:                         where, where, detail, null, null));
381:             });
382:         }
383:         return findings;
384:     }
