388:     /**
389:      * Migration guide for one attempt, generated from its STORED findings and impacts
390:      * only. Parameter names are restored by re-parsing the attempt's raw YAML (the
391:      * engine's finding envelopes deliberately omit them); a parse failure degrades to an
392:      * index without parameter names — actions stay grounded either way.
393:      */
394:     public Map<String, Object> migrationGuide(long attemptId) {
395:         RegistryStore.AttemptRow attempt = requireAttempt(attemptId);
396:         String slug = store.serviceSlug(attempt.serviceId()).orElse("(unknown)");
397:         List<RegistryStore.StoredFinding> findings = store.findingsForAttempt(attempt.id());
398:         Map<Long, List<RegistryStore.StoredImpact>> impactsByFinding = new LinkedHashMap<>();
399:         for (RegistryStore.StoredImpact impact : store.impactsForAttempt(attempt.id())) {
400:             impactsByFinding.computeIfAbsent(impact.findingId(), k -> new ArrayList<>()).add(impact);
401:         }
402:         Map<String, String> paramNames = paramIndexSafely(attempt.rawYaml());
403:         List<MigrationGuide.Step> steps = MigrationGuide.build(findings, impactsByFinding, paramNames);
404:         Map<String, Object> out = new LinkedHashMap<>();
405:         out.put("service", slug);
406:         out.put("version", attempt.incomingVersion());
407:         out.put("state", attempt.state());
408:         out.put("steps", steps.stream().map(MigrationGuide.Step::view).toList());
409:         out.put("note", steps.isEmpty()
410:                 ? "no compatibility findings for this attempt - no migration required"
411:                 : "generated from the attempt's stored findings; consumers are named from the"
412:                         + " stored impact analysis");
413:         return out;
414:     }
