589:     /** Changelog built from the actual stored findings of every published transition. */
590:     public Map<String, Object> changelog(String slug) {
591:         RegistryStore.ServiceRow service = requireService(slug);
592:         List<Map<String, Object>> entries = new ArrayList<>();
593:         for (RegistryStore.AttemptSummary attempt : store.listAttempts(service.id())) {
594:             if (!isPublished(attempt.state())) {
595:                 continue;
596:             }
597:             RegistryStore.AttemptRow row = store.findAttempt(attempt.id()).orElse(null);
598:             if (row == null) {
599:                 continue;
600:             }
601:             JsonNode decision = parseDecision(row.decisionJson());
602:             List<RegistryStore.StoredFinding> findings = store.findingsForAttempt(attempt.id());
603:             Map<Long, List<RegistryStore.StoredImpact>> impactsByFinding = new LinkedHashMap<>();
604:             for (RegistryStore.StoredImpact impact : store.impactsForAttempt(attempt.id())) {
605:                 impactsByFinding.computeIfAbsent(impact.findingId(), k -> new ArrayList<>()).add(impact);
606:             }
607:             List<Map<String, Object>> changes = new ArrayList<>();
608:             for (RegistryStore.StoredFinding finding : findings) {
609:                 Map<String, Object> view = new LinkedHashMap<String, Object>();
610:                 view.put("code", finding.code());
611:                 view.put("severity", finding.severity());
612:                 view.put("location", finding.location());
613:                 view.put("fieldPath", finding.fieldPath());
614:                 view.put("detail", finding.detail());
615:                 List<String> consumers = new ArrayList<>();
616:                 for (RegistryStore.StoredImpact impact : impactsByFinding.getOrDefault(finding.id(), List.of())) {
617:                     consumers.add(impact.consumer() + " (" + impact.level().toUpperCase() + ")");
618:                 }
619:                 if (!consumers.isEmpty()) {
620:                     view.put("consumerImpact", consumers);
621:                 }
622:                 changes.add(view);
623:             }
624:             List<String> affected = store.affectedConsumers(attempt.id());
625:             Map<String, Object> entry = new LinkedHashMap<>();
626:             entry.put("version", row.incomingVersion());
627:             entry.put("previousVersion", decision == null ? null : textOrNull(decision, "previousVersion"));
628:             entry.put("decision", row.state());
629:             entry.put("publishedAt", row.decidedAt() == null ? null : row.decidedAt().toString());
630:             entry.put("publishedBy", row.decidedBy());
631:             if ("overridden_published".equals(row.state())) {
632:                 entry.put("justification", row.justification());
633:             }
634:             entry.put("summary", Map.of(
635:                     "breaking", countSeverity(findings, "breaking"),
636:                     "warn", countSeverity(findings, "warn"),
637:                     "info", countSeverity(findings, "info")));
638:             entry.put("compatibilityChanges", changes);
639:             entry.put("migration", MigrationGuide.build(findings, impactsByFinding,
640:                     paramIndexSafely(row.rawYaml())).stream()
641:                     .map(MigrationGuide.Step::view).toList());
642:             entry.put("policyWarnings", decision == null ? List.of()
643:                     : findingListOf(decision, "policyFindings"));
644:             entry.put("affectedConsumers", affected);
645:             entries.add(entry);
646:         }
647:         Map<String, Object> out = new LinkedHashMap<>();
648:         out.put("service", slug);
649:         out.put("entries", entries);
650:         return out;
651:     }
