44:     private static int tightness(String key, JsonNode oldValue, JsonNode newValue) {
45:         boolean bothNumbers = oldValue.isNumber() && newValue.isNumber();
46:         return switch (key) {
47:             case "minimum", "minLength", "minItems", "minProperties" -> Double.compare(num(newValue), num(oldValue));
48:             case "maximum", "maxLength", "maxItems", "maxProperties" -> Double.compare(num(oldValue), num(newValue));
49:             // OpenAPI 3.1 writes exclusive bounds as numbers, 3.0 as booleans beside min/max
50:             case "exclusiveMinimum" -> bothNumbers
51:                     ? Double.compare(num(newValue), num(oldValue))
52:                     : booleanTightness(oldValue, newValue);
53:             case "exclusiveMaximum" -> bothNumbers
54:                     ? Double.compare(num(oldValue), num(newValue))
55:                     : booleanTightness(oldValue, newValue);
56:             // Regular languages are not ordered: a pattern change is directional only in
57:             // the trivial all-accepting case; otherwise the direction is unknowable.
58:             case "pattern" -> isAcceptAll(newValue) ? 1 : isAcceptAll(oldValue) ? -1 : UNKNOWN_DIRECTION;
59:             // For multiples, divisibility decides the direction (multiples of 4 are a
60:             // subset of multiples of 2); anything else is unordered.
61:             case "multipleOf" -> multipleOfTightness(oldValue, newValue);
62:             // Format vocabularies are unordered name sets.
63:             case "format" -> UNKNOWN_DIRECTION;
64:             case "uniqueItems" -> booleanTightness(oldValue, newValue);
65:             default -> 0;
