/**
 * Parameter serialization attributes (style/explode/allowReserved) change how the
 * parameter value appears on the wire, so they belong in the envelope. Only
 * deviations from the OpenAPI defaults are recorded, so making an implicit default
 * explicit stays wire-neutral; allowReserved only applies to query parameters (OAS 3.0).
 */
private void addSerialization(JsonNode param, String in, ObjectNode envelope) {
    String defaultStyle = "query".equals(in) || "cookie".equals(in) ? "form" : "simple";
    JsonNode styleNode = param.get("style");
    String style = styleNode != null && styleNode.isString() && !styleNode.stringValue().isBlank()
            ? styleNode.stringValue() : defaultStyle;
    boolean defaultExplode = "form".equals(style);
    JsonNode explodeNode = param.get("explode");
    boolean explode = explodeNode != null && explodeNode.isBoolean()
            ? explodeNode.booleanValue() : defaultExplode;
    TreeMap<String, JsonNode> ser = new TreeMap<>();
    if (!style.equals(defaultStyle)) {
        ser.put("style", JsonMappers.textNode(style));
    }
    if (explode != defaultExplode) {
        ser.put("explode", JsonNodeFactory.instance.booleanNode(explode));
    }
    JsonNode allowReserved = param.get("allowReserved");
    if ("query".equals(in) && allowReserved != null && allowReserved.isBoolean()
            && allowReserved.booleanValue()) {
        ser.put("allowReserved", JsonNodeFactory.instance.booleanNode(true));
    }
    if (!ser.isEmpty()) {
        TreeMap<String, JsonNode> wrapper = new TreeMap<>();
        wrapper.put("x-serialization", JsonMappers.objectNodeFrom(ser));
        envelope.set("x-serialization", JsonMappers.objectNodeFrom(wrapper).get("x-serialization"));
    }
}
```
