        // allowReserved is query-only: recorded for query...
        String reserved = HEADER + """
                  /c:
                    get:
                      parameters:
                        - {name: q, in: query, allowReserved: true, schema: {type: string}}
                      responses: {'200': {description: ok}}
                """;
